window.GTA_BUNDLE_INDEX = [{"file":"black-sanctum.json","title":"Black Sanctum","year":1982,"description":"Mark Data Products' CoCo classic, rebuilt from the original map and walkthroughs: a snowbound cabin, a mirror, and the coven beyond it."},{"file":"zork1.json","title":"Zork I (excerpt)","year":1980,"description":"The white house, the forest, the troll and the first caves of the Great Underground Empire. MIT-licensed since 2025."},{"file":"colossal-cave.json","title":"Colossal Cave Adventure (excerpt)","year":1977,"description":"Crowther & Woods' original: the well house, XYZZY, the little bird and the snake in the Hall of the Mountain King."},{"file":"st-hilarion.json","title":"The Abbey of St. Hilarion","year":2026,"description":"An original gothic adventure: an abandoned 18th-century monastery and the black magic beneath its chapel."},{"file":"postcard-tour.json","title":"The Postcard Tour (image demo)","year":2026,"description":"Three rooms drawn from photographs loaded by URL, with vector fallbacks."}];
window.GTA_BUNDLE = {"adventures/black-sanctum.json":{"format":"gta-1","id":"black-sanctum","title":"BLACK SANCTUM","author":"Recreation of the Mark Data Products adventure (TRS-80 Color Computer). Map and puzzle structure follow the original; room text is newly written.","theme":"coco","maxScore":100,"maxCarry":10,"start":"mt_country","intro":"Snow. Wind. Night coming on fast in the high country.\n\nYou took shelter from the storm in an old cabin you remembered from your boyhood hunting trips... but tonight there is a light burning in its window, and a terrible quiet all around.\n\nDuring the game you will discover what you must do. Save often - this is a dangerous place.\n\n(Type HELP for instructions.)","help":"Use VERB NOUN commands: GO CABIN, GET SHOVEL, OPEN DOOR, GO DOOR, GO STAIRS, GO MIRROR, LOOK MANTLE, READ NOTE, LIGHT LANTERN, PLAY FUGUE, PULL NAILS, CUT HAIR... Directions: N S E W U D. LOOK (L) describes the room; INVENTORY (I) lists what you carry. GET ALL and DROP ALL work. You can carry only 10 things. SAVE, RESTORE, UNDO and SCORE work any time.","ranks":[[0,"Lost Traveller"],[25,"Seeker"],[50,"Initiate"],[75,"Exorcist"],[100,"Bishop's Champion"]],"colors":{"ablue":"#2f6bff","aorange":"#ff7a1a","snow":"#f2f2ff"},"messages":{"dark":"It is pitch dark. You can't see a thing - but you can hear something scraping in the blackness.","noExit":"You can't go that way.","won":"*** THE BLACK SANCTUM IS DESTROYED ***"},"darkArt":[["bg","black"]],"artLib":{"snowy":[["bg","black"],["stars",40,"white",17,60],["mountains",100,"ablue",4,50],["mountains",120,"white",8,30],["ground",130,"snow"],["dither",0,130,256,62,"snow","ablue","sparse"]],"wire":[["room","black","black","black","white"]],"corridor":[["room","black","black","black","white"],["dither",0,186,256,6,"black","ablue"],["line",[72,40,72,128],"white"],["line",[184,40,184,128],"white"]],"boardsdoor":[["line",[-18,-40,18,-24],"aorange",3],["line",[-18,-24,18,-40],"aorange",3],["line",[-18,-12,18,-12],"aorange",3]]},"rooms":{"mt_country":{"name":"Rugged mountain country","desc":"You stand in rugged mountain country, knee-deep in snow. Pine trees crowd the slopes around you, their needles dusted with white. Just to the east, smoke rises from the chimney of a small log cabin.","exits":{"north":"pines_1","south":"pines_1","west":"pines_1","east":"outside_cabin"},"art":[["use","snowy"],["pine",30,160,70,"darkgreen","darkbrown"],["pine",64,150,50,"darkgreen","darkbrown"],["pine",236,168,80,"darkgreen","darkbrown"],["dither",18,104,20,50,"darkgreen","snow","sparse"],["rect",150,110,50,30,"darkbrown","black"],["poly",[144,110,206,110,175,92],"snow","black"],["rect",188,90,6,14,"darkstone"],["rect",170,122,8,18,"black"],["rect",156,118,8,6,"aorange"],["glow",160,120,12,"aorange",0.4],["alpha",0.5],["circle",192,82,4,"lightgray"],["circle",196,72,5,"lightgray"],["circle",202,60,6,"lightgray"],["alpha",1]]},"pines_1":{"name":"Pine forest","desc":"Pine trees, snow, and more pine trees. Every direction looks exactly the same, and the wind has already filled in your tracks.","exits":{"north":"pines_1","east":"pines_1","west":"pines_1","south":"pines_2"},"art":[["use","snowy"],["forest",110,"darkgreen",31,20],["dither",0,0,256,192,"none","white","sparse"]]},"pines_2":{"name":"Pine forest","desc":"More pines, bowed under the weight of the snow. Through a gap in the trees to the east you glimpse a warm orange light.","exits":{"north":"pines_1","south":"pines_1","west":"pines_1","east":"outside_cabin"},"art":[["use","snowy"],["forest",110,"darkgreen",37,14],["glow",240,130,30,"aorange",0.5]]},"outside_cabin":{"name":"Outside the cabin","desc":["You are standing before the door of a rough log cabin. Light flickers behind its frosted window. Snow is drifted high against the walls.",{"if":"open:cabin_door","text":"The cabin door is open.","else":"The cabin door is closed."},"The mountains lie west."],"exits":{"west":"mt_country","in":{"to":"living_room","door":"cabin_door"},"east":{"to":"living_room","door":"cabin_door"}},"art":[["bg","black"],["stars",20,"white",3,40],["rect",20,30,216,130,"darkbrown"],["dither",20,30,216,130,"darkbrown","black","lines"],["poly",[8,34,248,34,128,0],"snow","black"],["rect",34,70,40,34,"aorange","black"],["line",[54,70,54,104],"black",2],["line",[34,87,74,87],"black",2],["glow",54,86,30,"aorange",0.4],["if","open:cabin_door",[["rect",120,70,50,90,"aorange"],["glow",145,120,40,"yellow",0.4]],[["rect",120,70,50,90,"wood","black"],["circle",160,118,3,"gold"]]],["ground",160,"snow"],["poly",[0,160,0,120,30,150,60,160],"snow"],["poly",[256,160,256,110,220,150,200,160],"snow"]]},"living_room":{"name":"Living room","desc":["The cabin's living room is warm and smells of woodsmoke. A fire crackles in a stone fireplace beneath a heavy wooden mantle. Rough stairs climb to the floor above.",{"if":"open:cabin_door","text":"The front door stands open, and snow is blowing in across the floorboards.","else":"The front door is shut against the cold."}],"exits":{"out":{"to":"outside_cabin","door":"cabin_door"},"west":{"to":"outside_cabin","door":"cabin_door"},"up":"bedroom"},"art":[["room","darkbrown","wood","black","black"],["dither",72,40,112,88,"darkbrown","black","lines"],["rect",100,66,56,62,"stone","black"],["rect",110,88,36,40,"black"],["rect",92,62,72,6,"wood","black"],["poly",[116,128,140,128,136,112,128,100,120,112],"aorange"],["poly",[122,128,134,128,130,116,128,108,126,116],"yellow"],["glow",128,116,40,"aorange",0.35],["if","open:cabin_door",[["door","left",0.45,"black",true],["dither",0,150,70,42,"none","snow","sparse"]],[["door","left",0.45,"wood"]]],["stairs","up","wood",0.55,"right"]]},"bedroom":{"name":"Dimly lit bedroom","desc":"A dimly lit bedroom under the eaves. A young woman lies upon the bed, deathly pale and perfectly still. She is breathing - barely. There is a closet in the far wall. Stairs lead down.","exits":{"down":"living_room","in":"closet"},"art":[["room","darkbrown","wood","black","black"],["dither",72,40,112,88,"darkbrown","black","lines"],["door","back",0.75,"wood",true,0.24,0.8],["stairs","down","wood",0.15],["poly",[40,170,170,150,200,170,70,192],"white","black"],["rect",40,150,6,30,"wood"],["if","here:sheet",[["poly",[80,168,160,156,186,168,104,184],"ablue"]]],["ellipse",74,160,10,6,"skin"],["if","flag:hair_cut",[["ellipse",70,158,8,4,"aorange"]],[["poly",[64,156,84,154,96,170,66,176],"aorange"]]],["candle",220,150,12,"white"]]},"closet":{"name":"Large closet","desc":"A walk-in closet, far larger than the cabin ought to hold. Mothballs and old furs. On the back wall hangs a tall mirror in a black frame - and your reflection in it is a little too slow to follow you.","exits":{"out":"bedroom","north":{"to":"corridor_8","if":"has:robe","msg":"Your hand meets cold, hard glass. Your reflection shakes its head at you - as if you were missing something.","say":"The emblem on the hooded robe flares with a dull red light. The glass goes soft as water, and you step through..."}},"art":[["room","darkbrown","wood","black","black"],["ellipse",128,84,32,46,"black","white",3],["dither",100,44,56,80,"black","ablue","sparse"],["ellipse",128,84,32,46,null,"darkgray",2],["line",[20,40,60,46],"white",2],["poly",[24,44,34,44,40,130,18,130],"darkgray","black"],["poly",[42,46,52,46,58,126,38,126],"brown","black"],["line",[196,46,236,40],"white",2],["poly",[222,44,232,44,240,130,216,130],"darkgray","black"]]},"corridor_8":{"name":"Long narrow corridor","desc":"A long narrow corridor of black stone. Behind you, the mirror shimmers like the surface of a pond - the way back to the cabin. The corridor leads south. The air here is cold, and very old.","exits":{"south":"corridor_9","north":{"to":"closet","say":"You step back through the rippling glass..."}},"art":[["use","corridor"],["ellipse",128,84,18,30,"black","white",2],["dither",112,58,32,52,"black","ablue","sparse"]]},"corridor_9":{"name":"Long narrow corridor","desc":["A long narrow corridor. A bronze plaque is set into the wall beside a heavy wooden door,",{"if":"open:wooden_door","text":"which stands open.","else":"which is closed."},"Passages lead north, east and west."],"exits":{"north":"corridor_8","east":"corridor_19","west":"corridor_14","in":{"to":"organ_room","door":"wooden_door"}},"art":[["use","corridor"],["if","open:wooden_door",[["door","left",0.5,"black",true]],[["door","left",0.5,"wood"]]],["wall","right",0.45,0.65,0.45,0.6,"aorange","white"]]},"organ_room":{"name":"Impressive room","desc":["An impressive, vaulted hall. A great pipe organ fills the far wall, its pipes soaring up into darkness. Stone statues of robed and hooded figures stand along the walls, heads bowed.",{"if":"flag:fugue","text":"A section of the wall beside the organ has swung away to reveal a passage."},"A wooden door leads out."],"exits":{"out":{"to":"corridor_9","door":"wooden_door"},"north":{"to":"corridor_9","door":"wooden_door"},"in":{"to":"strange_room","if":"flag:fugue","msg":"You can't go that way."}},"art":[["room","black","black","black","white"],["rect",84,40,88,88,"black"],["rect",88,46,6,64,"white"],["rect",98,40,6,70,"white"],["rect",108,34,6,76,"aorange"],["rect",118,28,6,82,"white"],["rect",128,24,6,86,"aorange"],["rect",138,28,6,82,"white"],["rect",148,34,6,76,"aorange"],["rect",158,40,6,70,"white"],["rect",166,46,4,64,"white"],["rect",96,110,64,18,"ablue","white"],["line",[100,116,156,116],"white"],["statue",26,170,60,"lightgray"],["statue",230,170,60,"lightgray"],["statue",56,146,36,"gray"],["statue",200,146,36,"gray"],["if","flag:fugue",[["arch","back",0.92,"black","aorange",0.14,0.6]]]]},"strange_room":{"name":"Strange room","desc":"A strange, many-sided room. A circle of white salt has been poured on the floor, and within it stands a tall lectern. The candles here burn with a cold, colourless flame. A passage leads back to the organ hall, and a narrow opening - an old air vent - is set low in one wall.","exits":{"out":"organ_room","south":"organ_room","down":"arched_passage"},"art":[["room","black","black","black","aorange"],["ellipse",128,162,70,20,null,"white",3],["rect",120,112,16,48,"wood","black"],["poly",[110,112,146,112,140,102,116,102],"wood","black"],["rect",16,172,30,14,"black","white"],["line",[20,176,42,176],"white"],["line",[20,180,42,180],"white"],["candle",60,130,14,"white"],["candle",196,130,14,"white"]]},"arched_passage":{"name":"Arched passage","dark":true,"desc":["A low arched passage of dripping stone. Worn stone steps lead north, down into the crypt. The vent you crawled through is above you.",{"if":"flag:nails_pulled","text":"A doorway in the east wall stands open.","else":"There is a doorway in the east wall, boarded up from the other side."}],"exits":{"up":"strange_room","north":"crypt","east":{"to":"alcove","if":"flag:nails_pulled","msg":"The doorway is boarded up from the other side."}},"art":[["bg","black"],["dither",0,0,256,192,"darkstone","black","sparse"],["arch","back",0.5,"black","white",0.6,0.6],["line",[96,150,160,150],"white"],["line",[104,140,152,140],"white"],["line",[110,132,146,132],"white"],["if","flag:nails_pulled",[["rect",210,70,30,90,"black","white"]],[["rect",210,70,30,90,"wood","white"],["line",[210,90,240,100],"black",2],["line",[210,130,240,120],"black",2]]]]},"crypt":{"name":"Underground crypt","dark":true,"desc":["An underground crypt, low and airless. A heavy stone coffin rests in the centre of the floor,",{"if":"open:coffin","text":"its lid pushed aside.","else":"its lid firmly closed."},{"if":"flag:altar_built","text":"Beside it stands the altar you built, scorched black."},"Steps lead south."],"exits":{"south":"arched_passage"},"art":[["room","black","black","black","white"],["poly",[70,176,186,176,170,140,86,140],"darkstone","white"],["if","open:coffin",[["poly",[90,168,166,168,156,146,100,146],"black","white"],["skull",110,158,5,"white"],["poly",[170,150,220,136,230,150,180,164],"darkstone","white"]],[["poly",[86,140,170,140,160,128,96,128],"stone","white"]]],["if","flag:altar_built",[["rect",196,120,46,40,"darkbrown","white"],["alpha",0.6],["glow",218,116,30,"ablue",0.5],["alpha",1]]]]},"corridor_14":{"name":"Long narrow corridor","desc":"A long narrow corridor. The stone walls sweat with cold. Passages branch north, south and east.","exits":{"east":"corridor_9","south":"corridor_21","north":"small_room"},"art":[["use","corridor"],["arch","left",0.5,"black","white",0.25,0.6],["arch","right",0.5,"black","white",0.25,0.6]]},"small_room":{"name":"Small room","desc":"A small, bare room with whitewashed walls. Someone has scratched tally marks into the plaster - hundreds of them. Exits lead south and west.","exits":{"south":"corridor_14","west":"corridor_16"},"art":[["room","white","lightgray","white","black"],["text",86,80,"IIII IIII IIII","black",8],["text",86,90,"IIII IIII IIII","black",8],["text",86,100,"IIII IIII II","black",8]]},"corridor_16":{"name":"Long narrow corridor","desc":"A long narrow corridor. Somewhere above you, floorboards creak. Passages lead north, south and east.","exits":{"north":"corridor_19","south":"corridor_17","east":"small_room"},"art":[["use","corridor"],["arch","right",0.4,"black","white",0.25,0.6]]},"corridor_17":{"name":"End of corridor","desc":"The corridor ends at the foot of a steep, narrow stair leading up. You can hear someone muttering above. The corridor runs back north.","exits":{"north":"corridor_16","up":"loft"},"art":[["use","wire"],["stairs","up","darkgray",0.5,"back"],["line",[72,128,184,128],"white"]]},"loft":{"name":"Upstairs loft","desc":"A cramped loft under a steeply pitched roof. Cobwebs, broken chairs, old trunks. A hole in the floor leads down to the stair.","exits":{"down":"corridor_17"},"art":[["bg","black"],["poly",[0,0,128,0,0,110],"darkbrown","white"],["poly",[256,0,128,0,256,110],"darkbrown","white"],["line",[0,40,70,0],"white"],["line",[256,40,186,0],"white"],["poly",[0,192,256,192,220,120,36,120],"wood","white"],["rect",180,130,50,30,"darkbrown","white"],["rect",30,140,40,26,"darkbrown","white"],["line",[100,0,112,30,130,20,150,40],"lightgray"]]},"corridor_19":{"name":"Long narrow corridor","desc":"A long narrow corridor. To the north a doorway spills dusty yellow light. Passages lead west and south.","exits":{"west":"corridor_9","north":"study","south":"corridor_16"},"art":[["use","corridor"],["rect",108,64,40,64,"aorange","white"],["glow",128,100,40,"yellow",0.3]]},"study":{"name":"Old study","desc":"An old study. Bookcases stuffed with crumbling books cover the walls from floor to ceiling. A reading desk is buried under papers and loose sheet music. Exits lead south and west.","exits":{"south":"corridor_19","west":"corridor_21"},"art":[["room","darkbrown","darkred","black","white"],["bookcase",74,42,108,86,"darkbrown"],["texture","left","darkbrown","aorange","lines"],["texture","right","darkbrown","ablue","lines"],["table",96,150,64,28,"wood"],["rect",104,144,14,6,"white"],["rect",126,142,18,8,"white"],["line",[128,146,142,146],"black"]]},"corridor_21":{"name":"Long narrow corridor","desc":"A long narrow corridor. From the south comes a faint draught carrying the smell of lamp oil. Passages lead north, south and east.","exits":{"north":"corridor_14","south":"corridor_22","east":"study"},"art":[["use","corridor"],["arch","right",0.5,"black","white",0.25,0.6]]},"corridor_22":{"name":"End of corridor","desc":"The corridor ends here at a blank stone wall. A small alcove opens to the east. The way back is north.","exits":{"north":"corridor_21","east":"alcove"},"art":[["use","wire"],["rect",72,40,112,88,"darkstone","white"],["dither",72,40,112,88,"darkstone","black","brick"],["arch","right",0.5,"black","white",0.3,0.6]]},"alcove":{"name":"Small alcove","desc":["A small alcove.",{"if":"flag:nails_pulled","text":"In the back wall is an open doorway leading into darkness.","else":"In the back wall is a doorway, boarded up with planks nailed firmly across it."},"The corridor is west."],"exits":{"west":"corridor_22","in":{"to":"arched_passage","if":"flag:nails_pulled","msg":"The doorway is boarded up."},"east":{"to":"arched_passage","if":"flag:nails_pulled","msg":"The doorway is boarded up."}},"art":[["room","darkstone","darkstone","black","white"],["rect",106,56,44,72,"black","white"],["if","!flag:nails_pulled",[["group",128,112,1.1,[["use","boardsdoor"]]],["rect",108,76,40,4,"aorange"],["rect",108,92,40,4,"aorange"]]]]}},"items":{"cabin":{"name":"cabin","nouns":["cabin","smoke","chimney"],"adj":["log","small"],"at":"mt_country","scenery":true,"desc":"A small log cabin. Smoke curls from its chimney, and its window glows. Someone is home.","goes":"east"},"trees":{"name":"pine trees","nouns":["trees","tree","pines","pine","forest"],"at":["mt_country","pines_1","pines_2","outside_cabin"],"scenery":true,"desc":"Tall pines, heavy with snow."},"needles":{"name":"pine needles","nouns":["needles","needle","sprig","pine"],"adj":["pine"],"article":"some","at":"mt_country","here":"Fallen pine needles lie scattered on the snow.","desc":"A handful of fragrant pine needles. Evergreen - the tree that does not die.","art":[["line",[-6,0,6,-6],"darkgreen",2],["line",[-2,-2,-4,-7],"darkgreen"],["line",[2,-4,1,-9],"darkgreen"],["line",[4,-5,8,-9],"darkgreen"]]},"shovel":{"name":"shovel","nouns":["spade"],"at":"outside_cabin","here":"A snow shovel leans against the cabin wall.","desc":"A broad wooden snow shovel.","art":[["line",[-10,0,8,-26],"wood",2],["poly",[-16,2,-9,-6,-2,0,-10,6],"lightgray","black"]]},"cabin_door":{"name":"cabin door","nouns":["door"],"adj":["cabin","front","wooden"],"at":["outside_cabin","living_room"],"scenery":true,"open":false,"desc":[{"if":"open:cabin_door","text":"The door is open.","else":"A sturdy plank door. It's closed, but not locked."}]},"fireplace":{"name":"fireplace","nouns":["fireplace","fire","hearth"],"adj":["stone"],"at":"living_room","scenery":true,"desc":"A fieldstone fireplace with a cheerful fire. Somebody built it up not long ago. Above it is a heavy wooden mantle."},"mantle":{"name":"mantle","nouns":["mantle","mantel","shelf"],"adj":["wooden","heavy"],"at":"living_room","scenery":true,"container":true,"surface":true,"desc":"A heavy beam of old oak.","on":{"examine,search":{"do":[{"if":"hidden:matches","then":["Running your hand along the dusty mantle, you find a box of matches.",{"show":"matches"}],"else":"A heavy beam of old oak."}]}}},"matches":{"name":"box of matches","nouns":["matches","match","box"],"at":"mantle","hidden":true,"desc":"A box of wooden kitchen matches.","art":[["rect",-5,-4,10,4,"aorange","black"],["rect",-5,-4,3,4,"white"]]},"wine":{"name":"bottle of wine","nouns":["wine","bottle"],"adj":["red"],"at":"living_room","here":"A bottle of wine stands on a small table by the fire.","desc":"A dusty bottle of strong red wine.","art":[["rect",-3,-12,6,12,"darkred","black"],["rect",-1,-17,2,5,"darkred"]],"on":{"drink":"You'd better not. You need your wits about you tonight."}},"net":{"name":"butterfly net","nouns":["net"],"adj":["butterfly"],"at":"living_room","here":"A butterfly net hangs on a hook by the door.","desc":"A butterfly net on a long cane handle. Odd thing to keep in a mountain cabin.","art":[["line",[-12,0,6,-18],"wood",2],["ellipse",10,-22,7,5,null,"white"],["dither",4,-26,12,8,"none","white","sparse"]]},"snow":{"name":"snow","nouns":["snow","snowdrift","drift"],"at":["living_room","outside_cabin","mt_country","pines_1","pines_2"],"scenery":true,"desc":"Clean, deep mountain snow.","on":{"take,fill,put":{"if":{"any":["!in:living_room","open:cabin_door"]},"do":[{"if":"has:jug","then":["You scoop up handfuls of clean snow and pack the jug full.",{"destroy":"jug","give":"snow_jug","score":5}],"else":"You scoop up some snow, but it melts through your fingers. You need something to carry it in."}],"else":["The door is shut. There's no snow in here."]}}},"stairs":{"name":"stairs","nouns":["stairs","staircase","steps","stair"],"at":["living_room","bedroom","corridor_17","loft","arched_passage"],"scenery":true,"desc":"Steep, worn steps."},"bed":{"name":"bed","nouns":["bed"],"at":"bedroom","scenery":true,"desc":[{"if":"here:sheet","text":"A narrow bed, made up with a clean white sheet.","else":"A narrow bed with a bare straw mattress."}]},"sheet":{"name":"white sheet","nouns":["sheet","linen","cloth"],"adj":["white","clean"],"at":"bedroom","scenery":false,"here":"The bed is made up with a clean white sheet.","desc":"A clean white linen sheet. It would make a fine altar cloth.","art":[["poly",[-10,0,10,0,8,-4,-8,-4],"white","lightgray"]],"takeMsg":"You gently draw the sheet from beneath the woman. She does not stir."},"woman":{"name":"woman","nouns":["woman","girl","lady","body","hair"],"adj":["young","pale"],"at":"bedroom","scenery":true,"desc":["She is young, and very beautiful, and very cold. Her lips move faintly as though she is trying to speak a word she cannot remember.",{"if":"!flag:hair_cut","text":"Her long red hair spills across the pillow."},{"if":"flag:hair_cut","text":"A lock of her red hair has been cut away."},{"if":"hidden:note","text":"Clutched in her hand is a folded note."}],"on":{"wake,kiss,touch":"She doesn't respond. Whatever holds her is stronger than sleep.","cut":{"if":["has:shears","!flag:hair_cut"],"do":["With the shears you carefully snip away a long lock of her red hair. Forgive me, you whisper.",{"set":"hair_cut","give":"hair","score":5}],"else":[{"if":"flag:hair_cut","then":"You've already taken a lock of her hair.","else":"You have nothing to cut with."}]}}},"note":{"name":"note","nouns":["note","paper","letter"],"adj":["folded"],"at":"bedroom","hidden":true,"desc":"A folded note, written in a firm, educated hand.","text":"\"Whoever finds this - my sister is held by the Black Sanctum, the coven that meets beyond the glass. I have tried to break them and failed. The rite is written in the old study, on the other side. Raise the white altar in their crypt, scatter its ashes in their circle, and call upon the Bishop in the old tongue: INVOCARE EPISCOPUS. God keep you. - J.\"","art":[["rect",-5,-2,10,3,"white","black"]]},"closet_door":{"name":"closet","nouns":["closet","wardrobe"],"at":"bedroom","scenery":true,"desc":"A closet door in the far wall, standing ajar.","goes":"in"},"mirror":{"name":"mirror","nouns":["mirror","glass","reflection","frame"],"adj":["tall","black"],"at":["closet","corridor_8"],"scenery":true,"desc":[{"if":"in:closet","text":"A tall mirror in a black frame. Your reflection is wrong somehow - slow, and smiling when you are not. The glass looks almost... liquid."},{"if":"in:corridor_8","text":"From this side the mirror shows the closet, and the cabin beyond it. It ripples like water."}],"goes":"in","on":{"enter,go,climb,touch,push":{"if":"in:closet","do":[{"if":"has:robe","then":["The emblem on the hooded robe flares with a dull red light. The glass goes soft as water, and you step through...",{"goto":"corridor_8"}],"else":"Your hand meets cold, hard glass. Your reflection shakes its head at you - as if you were missing something."}],"else":["You step back through the rippling glass...",{"goto":"closet"}]}}},"robe":{"name":"hooded robe","nouns":["robe","hood","cloak","emblem"],"adj":["hooded","black"],"at":"closet","wearable":true,"here":"A black hooded robe hangs on a hook.","desc":"A black hooded robe of heavy wool. Over the heart is stitched an emblem: a raven within a circle, worked in red thread.","art":[["poly",[-6,0,6,0,4,-20,0,-24,-4,-20],"darkgray","white"],["circle",0,-14,2,"red"]]},"plaque":{"name":"bronze plaque","nouns":["plaque","sign"],"adj":["bronze"],"at":"corridor_9","scenery":true,"desc":"A bronze plaque, green with age, engraved with a raven within a circle.","text":"The engraving reads: \"HE WHO WOULD ENTER THE SANCTUM MUST FIRST PLAY THE MASTER'S FUGUE.\""},"wooden_door":{"name":"wooden door","nouns":["door"],"adj":["wooden","heavy"],"at":["corridor_9","organ_room"],"scenery":true,"open":false,"locked":true,"key":"keys","desc":[{"if":"open:wooden_door","text":"A heavy wooden door, standing open.","else":"A heavy wooden door bound with iron. There's a large keyhole."}],"unlockMsg":"One of the old man's keys turns in the lock with a heavy clunk."},"bookcases":{"name":"bookcases","nouns":["bookcases","bookcase","books","book","shelves","shelf"],"at":"study","scenery":true,"desc":"Floor-to-ceiling bookcases, stuffed with crumbling volumes.","on":{"examine,search,read":{"do":[{"var":"bookcase","add":1},{"if":"var:bookcase==1","then":"Dusty books on alchemy, demonology, plainsong. Nothing that leaps out at you. There are a great many books."},{"if":"var:bookcase==2","then":"You pull out armfuls of books. Mildew, mouse droppings, more mildew... but behind the third shelf something has been pushed to the back."},{"if":"var:bookcase==3","then":["Behind the books you find a bundle of handwritten pages - a manuscript - and a sheet of old parchment covered in musical notation.",{"show":["manuscript","parchment"]}]},{"if":"var:bookcase>3","then":"You've searched these bookcases thoroughly."}]}}},"papers":{"name":"papers","nouns":["papers","desk","music"],"adj":["reading","loose","sheet"],"at":"study","scenery":true,"desc":"Loose sheet music, most of it ordinary hymns. Nothing special - whatever is worth hiding here would be better hidden than this."},"manuscript":{"name":"manuscript","nouns":["manuscript","pages","bundle"],"adj":["handwritten"],"at":"study","hidden":true,"points":5,"desc":"A bundle of handwritten pages, tied with black ribbon.","text":"\"THE RITE OF UNMAKING. To break the Sanctum, raise an altar in its own crypt: of BOARDS joined with NAILS by HAMMER and SAW, dressed in a WHITE CLOTH. Upon it lay the living green that does not die (the PINE), a FEATHER of the coven's raven, a lock of HAIR from the one they hold, SALT from their own circle, and pure SNOW in an earthen vessel. Speak the word BUILD and the altar shall consume itself. Bear its ASHES into their circle and call upon the Bishop: INVOCARE EPISCOPUS.\"","art":[["rect",-6,-3,12,3,"white","black"],["line",[-6,-1,6,-1],"black"]]},"parchment":{"name":"parchment","nouns":["parchment","music","fugue","score"],"adj":["sheet","old"],"at":"study","hidden":true,"points":5,"desc":"A sheet of yellowed parchment, closely written with musical notation. Across the top is written: \"Fuga in Tenebris\" - the Fugue in Darkness.","text":"It is organ music: a fugue, dense and strange. You can read music well enough to play it, if you had an organ.","art":[["rect",-5,-4,10,4,"buff","black"],["line",[-4,-3,4,-3],"black"],["line",[-4,-1,4,-1],"black"]]},"old_man":{"name":"old man","nouns":["man","hermit","oldman"],"adj":["old"],"at":"loft","fixed":true,"here":"A wild-eyed old man sits on a trunk, clutching a ring of keys and muttering to himself.","desc":[{"if":"flag:man_drunk","text":"The old man is snoring happily, an empty wine bottle cradled in his arms.","else":"A ragged old man with wild eyes and a long dirty beard. He clutches a ring of keys and licks his cracked lips. \"Thirsty,\" he mutters. \"So very thirsty...\""}],"fixedMsg":"The old man swats your hands away.","art":[["ellipse",0,-18,10,16,"darkgray","white"],["circle",0,-38,7,"skin","white"],["poly",[-5,-36,5,-36,0,-24],"white"],["circle",-3,-40,1,"black"],["circle",3,-40,1,"black"]],"artAt":[205,132],"on":{"say,wake":{"if":"!flag:man_drunk","do":"\"Thirsty,\" he croaks. \"Got anything to drink, friend?\"","else":"He just snores."}}},"keys":{"name":"ring of keys","nouns":["keys","key","ring"],"adj":["iron"],"at":"loft","points":5,"hidden":false,"desc":"A heavy iron ring of old keys.","art":[["circle",0,-5,4,null,"lightgray",1.5],["line",[3,-3,8,0],"lightgray",1.5],["line",[-3,-3,-7,1],"lightgray",1.5]],"here":[{"if":"flag:man_drunk","text":"A ring of keys lies on the floor where the old man dropped it.","else":""}]},"shears":{"name":"shears","nouns":["shears","scissors"],"adj":["pair"],"article":"some","at":"loft","desc":"A pair of sharp sheep shears.","art":[["line",[-8,0,6,-10],"lightgray",2],["line",[-8,-10,6,0],"lightgray",2]]},"saw":{"name":"hand saw","nouns":["saw","handsaw"],"adj":["hand"],"at":"loft","desc":"A carpenter's hand saw.","art":[["poly",[-12,0,8,-4,8,-10,-12,-4],"lightgray","black"],["rect",8,-11,5,8,"wood"]]},"jug":{"name":"earthen jug","nouns":["jug","vessel","pitcher"],"adj":["earthen","clay","empty"],"at":"small_room","desc":"An empty earthenware jug.","art":[["ellipse",0,-6,6,7,"aorange","black"],["rect",-2,-15,4,4,"aorange","black"]]},"snow_jug":{"name":"jug of snow","nouns":["jug","snow","vessel"],"adj":["earthen","clay"],"at":null,"desc":"The earthen jug, packed with clean mountain snow. It doesn't seem to melt.","art":[["ellipse",0,-6,6,7,"aorange","black"],["ellipse",0,-13,4,2,"white"]]},"organ":{"name":"pipe organ","nouns":["organ","pipes","keyboard","keys"],"adj":["pipe","great"],"at":"organ_room","scenery":true,"desc":"A magnificent pipe organ. The keys are yellowed ivory; the stops are carved in the shape of ravens' heads."},"statues":{"name":"statues","nouns":["statues","statue","figures","monks"],"adj":["stone","hooded"],"at":"organ_room","scenery":true,"desc":"Life-size stone figures in hooded robes - the same robe you found in the cabin. Their faces are hidden. Every one of them is turned slightly toward the organ, as if listening."},"raven":{"name":"black raven","nouns":["raven","bird","crow"],"adj":["black"],"at":"strange_room","here":"A huge black raven perches on the lectern, watching you.","desc":"An enormous black raven with eyes like drops of blood. It does not blink.","art":[["ellipse",0,-8,7,6,"black","white"],["circle",6,-14,4,"black","white"],["poly",[9,-15,15,-13,9,-12],"lightgray"],["circle",7,-15,1,"red"],["poly",[-6,-8,-14,-4,-6,-4],"black","white"]],"artAt":[128,100]},"feather":{"name":"raven feather","nouns":["feather","quill"],"adj":["raven","black"],"at":null,"desc":"A long, glossy black feather from the coven's raven.","art":[["line",[-8,0,8,-12],"white"],["poly",[-6,-2,6,-11,8,-12,-4,0],"black","white"]]},"lectern":{"name":"lectern","nouns":["lectern","stand"],"at":"strange_room","scenery":true,"desc":"A tall wooden lectern carved with ravens. The book it once held is gone."},"circle":{"name":"circle of salt","nouns":["circle","salt","ring"],"at":"strange_room","scenery":true,"desc":[{"if":"here:ashes","text":"A wide circle of coarse white salt. Grey ashes are scattered within it.","else":"A wide circle of coarse white salt, poured with great care."}],"on":{"take":{"if":"hidden:salt","do":["You scrape up a handful of salt from the circle.",{"show":"salt","give":"salt","score":5}],"else":"You already have some of the salt."}}},"salt":{"name":"handful of salt","nouns":["salt"],"adj":["handful","coarse"],"at":"strange_room","hidden":true,"desc":"A handful of coarse white salt from the coven's circle.","art":[["ellipse",0,-2,6,3,"white","lightgray"]]},"vent":{"name":"vent","nouns":["vent","opening","hole","shaft"],"adj":["air","narrow"],"at":["strange_room","arched_passage"],"scenery":true,"desc":"A narrow opening, just wide enough to crawl through.","goes":"down","on":{"enter,go,climb":{"do":[{"if":"in:strange_room","then":[{"goto":"arched_passage"}],"else":[{"goto":"strange_room"}]}]}}},"passage":{"name":"passage","nouns":["passage","opening"],"at":"organ_room","scenery":true,"hidden":true,"desc":"A dark passage where the wall swung open.","on":{"enter,go":[{"goto":"strange_room"}]}},"coffin":{"name":"stone coffin","nouns":["coffin","lid","sarcophagus"],"adj":["stone","heavy","closed"],"at":"crypt","scenery":true,"container":true,"open":false,"desc":[{"if":"open:coffin","text":"The coffin is open. Inside lies a skeleton in the rags of a bishop's vestments.","else":"A heavy stone coffin. Carved on its lid is a bishop's mitre."}],"openMsg":"You strain against the stone lid. It grinds aside to reveal a skeleton dressed in the rotted vestments of a bishop."},"skeleton":{"name":"skeleton","nouns":["skeleton","bishop","bones","vestments"],"at":"coffin","scenery":true,"desc":"The bones of a bishop, his hands folded on his breast. The coven must have murdered him and laid him here in mockery. A faint warmth rises from him, even now."},"hammer":{"name":"claw hammer","nouns":["hammer"],"adj":["claw"],"at":"crypt","points":5,"desc":"A heavy claw hammer.","art":[["line",[-8,0,6,-12],"wood",2],["poly",[2,-16,12,-10,10,-8,0,-14],"lightgray","black"]]},"lantern":{"name":"lantern","nouns":["lantern","lamp","light"],"adj":["oil"],"at":"alcove","points":5,"lightable":true,"lit":false,"lightWith":"matches","needMsg":"You need something to light it with.","lightMsg":"You strike a match and light the lantern's wick. A warm glow spreads around you.","outMsg":"You turn down the wick. The lantern goes out.","desc":[{"if":"lit:lantern","text":"An oil lantern, burning brightly.","else":"An old oil lantern. It still has oil in it."}],"art":[["rect",-4,-12,8,10,"darkgray","white"],["rect",-3,-2,6,2,"darkgray"],["if","lit:lantern",[["glow",0,-7,14,"yellow",0.7]]]]},"boarded_door":{"name":"boarded doorway","nouns":["door","doorway"],"adj":["boarded"],"at":["alcove","arched_passage"],"scenery":true,"desc":[{"if":"flag:nails_pulled","text":"An open doorway.","else":"Planks nailed firmly across a doorway."}],"on":{"pull,remove,take,open,break":{"if":["in:alcove","!flag:nails_pulled"],"do":[{"if":"has:hammer","then":["You hook the claw of the hammer under each nail and lever it out with a long screech. One by one the planks come free, and the doorway stands open.",{"set":"nails_pulled","score":5},{"move":["boards","nails"],"to":"here"}],"else":"The nails are driven in deep. You can't pull them out with your fingers."}],"else":[{"if":"flag:nails_pulled","then":"The doorway is already open.","else":"The boards are nailed from the other side."}]}}},"boards":{"name":"boards","nouns":["boards","planks","board","plank","wood"],"article":"some","at":null,"desc":"Several stout wooden planks.","art":[["rect",-12,-3,24,3,"wood","black"],["rect",-10,-6,22,3,"wood","black"]]},"nails":{"name":"nails","nouns":["nails","nail"],"adj":["iron","bent"],"article":"some","at":null,"desc":"A handful of long iron nails, only slightly bent.","art":[["line",[-4,0,-2,-6],"lightgray"],["line",[0,0,1,-6],"lightgray"],["line",[3,0,5,-5],"lightgray"]]},"hair":{"name":"lock of hair","nouns":["hair","lock"],"adj":["red"],"at":null,"desc":"A long lock of red hair, tied with a thread.","art":[["line",[-6,0,-2,-4,2,-2,6,-6],"aorange",2]]},"altar":{"name":"altar","nouns":["altar"],"adj":["white","scorched"],"at":"crypt","scenery":true,"hidden":true,"desc":"The altar you built, scorched black by holy fire."},"ashes":{"name":"ashes","nouns":["ashes","ash","dust"],"adj":["grey","gray","holy"],"article":"some","at":null,"desc":"A double handful of fine grey ash, still faintly warm. It seems to glow when you aren't looking directly at it.","art":[["ellipse",0,-2,7,3,"lightgray"],["glow",0,-3,10,"ablue",0.4]]}},"actions":[{"verb":"go,enter","noun":["cabin"],"room":"mt_country","do":[{"goto":"outside_cabin"}]},{"verb":"go,enter","noun":["door"],"room":"outside_cabin","do":[{"if":"open:cabin_door","then":[{"goto":"living_room"}],"else":"The door is closed."}]},{"verb":"go,enter,exit","noun":["door","outside"],"room":"living_room","do":[{"if":"open:cabin_door","then":[{"goto":"outside_cabin"}],"else":"The door is closed."}]},{"verb":"go,climb","noun":["stairs","steps","stair"],"room":"living_room","do":[{"goto":"bedroom"}]},{"verb":"go,climb","noun":["stairs","steps","stair"],"room":"bedroom","do":[{"goto":"living_room"}]},{"verb":"go,climb","noun":["stairs","steps","stair"],"room":"corridor_17","do":[{"goto":"loft"}]},{"verb":"go,climb","noun":["stairs","steps","stair","hole"],"room":"loft","do":[{"goto":"corridor_17"}]},{"verb":"go,climb","noun":["stairs","steps","stair"],"room":"arched_passage","do":[{"goto":"crypt"}]},{"verb":"go,enter","noun":["closet"],"room":"bedroom","do":[{"goto":"closet"}]},{"verb":"go,enter,exit","noun":["closet","bedroom"],"room":"closet","do":[{"goto":"bedroom"}]},{"verb":"go,enter","noun":["door"],"room":"corridor_9","do":[{"if":"open:wooden_door","then":[{"goto":"organ_room"}],"else":"The wooden door is closed."}]},{"verb":"go,enter,exit","noun":["door"],"room":"organ_room","do":[{"goto":"corridor_9"}]},{"verb":"go,enter","noun":["door","doorway"],"room":"alcove","do":[{"if":"flag:nails_pulled","then":[{"goto":"arched_passage"}],"else":"The doorway is boarded up."}]},{"verb":"go,enter","noun":["door","doorway"],"room":"arched_passage","do":[{"if":"flag:nails_pulled","then":[{"goto":"alcove"}],"else":"The doorway is boarded up from the other side."}]},{"verb":"go,enter,exit","noun":["passage"],"room":"strange_room","do":[{"goto":"organ_room"}]},{"verb":"take,examine","noun":["note"],"room":"bedroom","if":"hidden:note","do":["You gently pry the note from the woman's cold fingers.",{"show":"note","give":"note"}]},{"verb":"take","noun":["hair"],"room":"bedroom","if":"!flag:hair_cut","do":[{"if":"has:shears","then":["With the shears you carefully snip away a long lock of her red hair.",{"set":"hair_cut","give":"hair","score":5}],"else":"You'd need something sharp to cut it."}]},{"verb":"cut","noun":["hair","woman","lock"],"room":"bedroom","if":["has:shears","!flag:hair_cut"],"do":["With the shears you carefully snip away a long lock of her red hair. Forgive me, you whisper.",{"set":"hair_cut","give":"hair","score":5}]},{"verb":"cut","noun":["hair","woman","lock"],"room":"bedroom","if":"!has:shears","do":"You have nothing to cut with."},{"verb":"give","noun":"wine","if":"here:old_man","do":["The old man's eyes light up. He snatches the bottle, pulls the cork with his teeth and drains it in one long swallow. \"Ahhhh... bless you, friend,\" he sighs, and topples backwards, snoring. The ring of keys slips from his fingers.",{"destroy":"wine","set":"man_drunk"}]},{"verb":"give","noun":"*","if":"here:old_man","do":"The old man shakes his head. \"Can't drink that,\" he mutters."},{"verb":"take","noun":"keys","if":["here:old_man","!flag:man_drunk"],"do":"The old man snarls and clutches the keys to his chest. \"Mine! Thirsty work, guarding keys...\""},{"verb":"play","noun":["fugue","parchment","music"],"if":"in:organ_room","do":[{"if":"!has:parchment","then":"You don't know the fugue by heart. You'd need the music.","else":[{"if":"flag:fugue","then":"You play the fugue again. The statues seem to sway.","else":["You spread the parchment on the music stand, pull out the stops, and begin to play. The Fugue in Darkness thunders through the hall - dissonant, tremendous, wrong. The statues seem to lean closer. As the last chord dies, stone grinds on stone, and a section of the wall beside the organ swings inward, revealing a passage.",{"set":"fugue","score":10,"show":"passage"}]}]}]},{"verb":"play","noun":["organ"],"if":"in:organ_room","do":[{"if":"has:parchment","then":"Perhaps you should play the FUGUE.","else":"You pick out a hymn on the organ. The great pipes groan, but nothing else happens. The statues seem... disappointed."}]},{"verb":"play","do":"There's nothing here to play."},{"verb":"take,catch","noun":"raven","if":"here:raven","do":[{"if":"has:net","then":["You swing the butterfly net. The raven shrieks and flaps, but it's caught fast in the mesh!",{"set":"raven_caught","give":"raven"}],"else":"You lunge for the raven. It slashes the back of your hand with its beak and hops out of reach, cackling."}]},{"verb":"take,pull,pluck","noun":["feather"],"if":["has:raven","!flag:feather_taken"],"do":["You pluck a long black feather from the struggling raven's tail. It screams curses at you in a voice almost human.",{"set":"feather_taken","give":"feather","score":10}]},{"verb":"pluck","noun":"raven","if":["has:raven","!flag:feather_taken"],"do":["You pluck a long black feather from the struggling raven's tail. It screams curses at you in a voice almost human.",{"set":"feather_taken","give":"feather","score":10}]},{"verb":"drop,free","noun":"raven","if":"has:raven","do":["You open the net. The raven explodes into the air, circles the room once, and settles back on the lectern, glaring.",{"move":"raven","to":"strange_room"}]},{"verb":"take","noun":["salt"],"room":"strange_room","if":"hidden:salt","do":["You scrape up a handful of salt from the circle.",{"show":"salt","give":"salt","score":5}]},{"verb":"pull,remove,take","noun":["nails","boards","planks","nail"],"room":"alcove","if":"!flag:nails_pulled","do":[{"if":"has:hammer","then":["You hook the claw of the hammer under each nail and lever it out with a long screech. One by one the planks come free, and the doorway stands open.",{"set":"nails_pulled","score":5},{"move":["boards","nails"],"to":"here"}],"else":"The nails are driven in deep. You'd need a tool to pull them."}]},{"verb":"dig","noun":["snow"],"do":[{"if":"has:shovel","then":"You shovel snow for a while. It feels good to do something ordinary.","else":"You'd need a shovel."}]},{"verb":"build,make,raise,construct","noun":["altar"],"if":"in:crypt","do":[{"if":"flag:altar_built","then":"The altar has already been built.","else":[{"if":["near:boards","near:nails","near:hammer","near:saw","near:sheet","near:needles","near:feather","near:hair","near:salt","near:snow_jug"],"then":["You saw the boards to length and nail them into a rough table, and drape the white sheet across it. Upon it you lay the pine needles, the raven's feather, the lock of red hair, the salt, and the jug of snow.\n\nFor a moment nothing happens. Then the open coffin breathes out a sigh of warm air - and the altar bursts into a silent blue-white flame. In the space of three heartbeats everything upon it is consumed. When the fire dies, only a little heap of grey ashes remains on the scorched wood.",{"set":"altar_built","show":"altar","score":15},{"destroy":["boards","nails","sheet","needles","feather","hair","salt","snow_jug"]},{"move":"ashes","to":"here"}],"else":["You don't yet have everything the rite requires here. According to the manuscript you still need:",{"if":"!near:boards","then":"  - boards"},{"if":"!near:nails","then":"  - nails"},{"if":"!near:hammer","then":"  - a hammer"},{"if":"!near:saw","then":"  - a saw"},{"if":"!near:sheet","then":"  - a white cloth"},{"if":"!near:needles","then":"  - the living green (pine)"},{"if":"!near:feather","then":"  - a feather of the raven"},{"if":"!near:hair","then":"  - a lock of hair"},{"if":"!near:salt","then":"  - salt from the circle"},{"if":"!near:snow_jug","then":"  - pure snow in an earthen vessel"}]}]}]},{"verb":"build,make,raise,construct","noun":["altar"],"do":"The manuscript says the altar must be raised in the Sanctum's own crypt."},{"verb":"throw,drop,pour,sprinkle,put","noun":"ashes","if":["has:ashes","in:strange_room"],"do":["You step into the circle and scatter the grey ashes across the salt. Where they fall, the salt hisses and smokes, and the cold candle-flames lean toward you as though a great wind were blowing. The raven begins to scream.",{"move":"ashes","to":"strange_room","set":"ashes_scattered"}]},{"verb":"say,invocare,invoke,call","noun":["invocare","episcopus","bishop"],"if":["flag:ashes_scattered","in:strange_room"],"do":["\"INVOCARE EPISCOPUS!\"\n\nYour voice booms like the organ. The ashes rise from the circle in a spinning column of light, and within it stands a tall figure in white and gold, a crozier in his hand - the murdered Bishop, his face terrible and kind.\n\nHe strikes the crozier once upon the stone. The salt circle bursts into white fire. Far away you hear a chorus of screams as every hooded statue in the organ hall cracks from crown to foot. The raven bursts into black smoke. The walls of the Sanctum groan and run like wax...\n\n...and you are standing in the cabin bedroom. Dawn light is pouring through the window. On the bed, the young woman opens her eyes, and smiles, and speaks one word: \"Thank you.\"",{"score":20},{"win":"The coven is broken. The Black Sanctum is no more."}]},{"verb":"say,invocare,invoke,call","noun":["invocare","episcopus","bishop"],"if":"in:bedroom","do":"You speak the words over the sleeping woman. Her lips move, as if repeating them... but she does not wake. The words need the rite behind them."},{"verb":"say,invocare,invoke,call","noun":["invocare","episcopus","bishop"],"do":"Your words echo strangely, then fade. Nothing happens - not here, not yet."},{"verb":"listen","room":"crypt","if":"open:coffin","do":"In the silence you hear - or imagine - a dry old voice from the coffin: \"Here. Build it here, my child, beside me. And then call me.\""},{"verb":"listen","room":"crypt","do":"Something shifts inside the stone coffin. Just settling, surely."},{"verb":"listen","room":"corridor_17","do":"From the loft above, an old man's voice: \"Thirsty... so thirsty...\""},{"verb":"listen","room":"corridor_21","do":"You hear a faint creak of hinges somewhere to the south."},{"verb":"listen","room":"organ_room","do":"The silence here has a waiting quality. Like an audience before a concert."}],"events":[{"if":"dark","do":[{"var":"darkturns","add":1},{"if":"var:darkturns==2","then":"Something scrapes across the stone close by. You'd better find some light."},{"if":"var:darkturns>=4","then":[{"die":"Something in the dark finds you first. Cold fingers close around your throat..."}]}]},{"if":"!dark","do":[{"var":"darkturns","value":0}]},{"if":["in:pines_1","chance:15"],"do":["Somewhere in the forest a wolf howls. Another answers it - closer."]}]},"adventures/zork1.json":{"format":"gta-1","id":"zork1-slice","title":"ZORK I: The Great Underground Empire","author":"Infocom (1980). Zork I is open source under the MIT License (Microsoft, 2025). This is an illustrated excerpt: the house, the forest, and the first caves.","theme":"infocom","maxScore":70,"start":"west_of_house","intro":"ZORK I: The Great Underground Empire\nCopyright (c) 1981, 1982, 1983 Infocom, Inc. All rights reserved.\nZORK is a registered trademark of Infocom, Inc.\n\n[This excerpt holds three treasures. Put all three in the trophy case to win.]","help":"Type commands like OPEN MAILBOX, READ LEAFLET, GO NORTH (N), TAKE LAMP, TURN ON LAMP, MOVE RUG, OPEN TRAP DOOR, KILL TROLL WITH SWORD, PUT EGG IN CASE. Don't wander around in the dark - you are likely to be eaten by a grue.","ranks":[[0,"Beginner"],[25,"Amateur Adventurer"],[45,"Novice Adventurer"],[60,"Junior Adventurer"],[70,"Adventurer"]],"messages":{"dark":"It is pitch black. You are likely to be eaten by a grue.","noExit":"You can't go that way.","won":"*** You have won (this excerpt of ZORK I) ***"},"artLib":{"day":[["gradient",0,110,"sky","cyan"],["circle",220,26,12,"yellow"],["ground",110,"grass"]],"whitehouse":[["rect",70,50,116,64,"white","black"],["poly",[62,50,194,50,160,22,96,22],"darkred","black"],["rect",150,10,12,18,"darkred","black"]],"boards":[["line",[86,66,106,76],"brown",3],["line",[150,66,170,76],"brown",3],["line",[86,76,106,66],"brown",3],["line",[150,76,170,66],"brown",3]],"trees":[["forest",112,"darkgreen",11,8]]},"rooms":{"west_of_house":{"name":"West of House","desc":"You are standing in an open field west of a white house, with a boarded front door.","exits":{"north":"north_of_house","south":"south_of_house","west":"forest_w","east":{"msg":"The door is boarded and you can't remove the boards."},"northeast":"north_of_house","southeast":"south_of_house"},"art":[["use","day"],["use","trees"],["use","whitehouse"],["rect",116,74,24,40,"wood","black"],["line",[112,82,144,90],"brown",4],["line",[112,100,144,92],"brown",4],["rect",84,66,22,14,"navy","black"],["rect",150,66,22,14,"navy","black"],["rect",36,140,4,30,"darkgray"],["rect",26,128,26,14,"white","black"],["rect",50,124,3,8,"red"]]},"north_of_house":{"name":"North of House","desc":"You are facing the north side of a white house. There is no door here, and all the windows are boarded up. To the north a narrow path winds through the trees.","exits":{"west":"west_of_house","east":"behind_house","north":"forest_path","southwest":"west_of_house","southeast":"behind_house","south":{"msg":"The windows are all boarded."}},"art":[["use","day"],["use","trees"],["use","whitehouse"],["rect",84,66,22,14,"navy","black"],["rect",150,66,22,14,"navy","black"],["use","boards"],["path","tan",112,30,8]]},"south_of_house":{"name":"South of House","desc":"You are facing the south side of a white house. There is no door here, and all the windows are boarded.","exits":{"west":"west_of_house","east":"behind_house","south":"forest_s","northwest":"west_of_house","northeast":"behind_house","north":{"msg":"The windows are all boarded."}},"art":[["use","day"],["use","trees"],["use","whitehouse"],["rect",84,66,22,14,"navy","black"],["rect",150,66,22,14,"navy","black"],["use","boards"]]},"behind_house":{"name":"Behind House","desc":["You are behind the white house. A path leads into the forest to the east. In one corner of the house there is a small window which is",{"if":"open:window","text":"open.","else":"slightly ajar."}],"exits":{"north":"north_of_house","south":"south_of_house","east":"clearing_e","northwest":"north_of_house","southwest":"south_of_house","west":{"to":"kitchen","door":"window"},"in":{"to":"kitchen","door":"window"}},"art":[["use","day"],["use","trees"],["use","whitehouse"],["if","open:window",[["rect",160,64,20,18,"black","white"]],[["rect",160,64,20,18,"navy","white"],["line",[160,66,180,66],"black"]]],["path","tan",112,50,6]]},"kitchen":{"name":"Kitchen","desc":["You are in the kitchen of the white house. A table seems to have been used recently for the preparation of food. A passage leads to the west and a dark staircase can be seen leading upward. A dark chimney leads down and to the east is a small window which is",{"if":"open:window","text":"open.","else":"slightly ajar."}],"exits":{"west":"living_room","up":"attic","east":{"to":"behind_house","door":"window"},"out":{"to":"behind_house","door":"window"},"down":{"msg":"Only Santa Claus climbs down chimneys."}},"onEnter":[{"if":"first","do":[{"score":10}]},{"if":"flag:trap_barred","do":[{"unset":"trap_barred"}]}],"art":[["room","buff","brown","lightgray","black"],["window","right",0.5,0.6,"sky","black",0.3,0.3],["stairs","up","darkbrown",0.35,"left"],["rect",106,86,44,42,"darkgray","black"],["rect",112,94,32,34,"black"],["door","left",0.75,"brown",true,0.18],["table",86,150,84,26,"wood"]]},"living_room":{"name":"Living Room","desc":["You are in the living room. There is a doorway to the east, a wooden door with strange gothic lettering to the west, which appears to be nailed shut, a trophy case,",{"if":"!flag:rug_moved","text":"and a large oriental rug in the center of the room."},{"if":["flag:rug_moved","!open:trap_door"],"text":"and a closed trap door at your feet."},{"if":["flag:rug_moved","open:trap_door"],"text":"and a rug lying beside an open trap door."}],"exits":{"east":"kitchen","west":{"msg":"The door is nailed shut."}},"art":[["room","tan","wood","buff","black"],["door","back",0.5,"darkbrown"],["text",114,70,"GNUSTO","gold",6],["arch","right",0.5,"black","brown",0.3,0.6],["wall","left",0.25,0.7,0.05,0.6,"darkbrown","black"],["wall","left",0.3,0.65,0.15,0.55,"lightgray","black"],["if","!flag:rug_moved",[["dpoly",[[70,182],[186,182],[168,142],[88,142]],"darkred","gold"],["poly",[[70,182],[186,182],[168,142],[88,142]],null,"gold"]],[["dpoly",[[160,186],[240,186],[214,150],[168,150]],"darkred","gold"],["if","open:trap_door",[["poly",[[90,176],[150,176],[142,148],[98,148]],"black","gray"],["poly",[[98,148],[142,148],[148,112],[92,112]],"wood","black"]],[["poly",[[90,176],[150,176],[142,148],[98,148]],"wood","black"],["rect",118,168,6,2,"gray"]]]]]]},"attic":{"name":"Attic","dark":true,"desc":"This is the attic. The only exit is a stairway leading down.","exits":{"down":"kitchen"},"art":[["bg","darkbrown"],["poly",[0,0,256,0,256,60,128,110,0,60],"wood","black"],["line",[0,60,128,110,256,60],"black",2],["poly",[0,192,256,192,200,130,56,130],"brown","black"],["stairs","down","gray",0.2],["table",150,130,60,20,"darkbrown"]]},"cellar":{"name":"Cellar","dark":true,"desc":"You are in a dark and damp cellar with a narrow passageway leading north, and a crawlway to the south. On the west is the bottom of a steep metal ramp which is unclimbable.","exits":{"north":"troll_room","south":"east_of_chasm","up":{"to":"living_room","door":"trap_door","if":"!flag:trap_barred","msg":"The trap door is closed."},"west":{"msg":"You try to ascend the ramp, but it is impossible, and you slide back down."}},"onEnter":[{"if":"first","do":[{"score":25}]},{"if":["has:sword","!flag:troll_dead"],"do":["Your sword is glowing with a faint blue glow."]}],"art":[["room","darkstone","darkstone","black","black"],["arch","back",0.5,"black","stone",0.25,0.5],["poly",[0,40,60,110,60,140,0,192],"gray","black"],["line",[0,60,60,120],"lightgray"],["wall","ceiling",0.4,0.6,0.3,0.6,"wood","black"],["poly",[100,192,156,192,146,176,110,176],"black"]]},"troll_room":{"name":"The Troll Room","dark":true,"desc":"This is a small room with passages to the east and south and a forbidding hole leading west. Bloodstains and deep scratches (perhaps made by an axe) mar the walls.","exits":{"south":"cellar","west":{"to":"maze_1","if":"flag:troll_dead","msg":"The troll fends you off with a menacing gesture."},"east":{"to":"ew_passage","if":"flag:troll_dead","msg":"The troll fends you off with a menacing gesture."}},"onEnter":[{"if":["!flag:troll_dead","has:sword"],"do":["Your sword has begun to glow very brightly."]}],"art":[["cave","darkstone","black","stone",31],["line",[30,60,40,90,34,110],"darkred",3],["line",[220,70,214,96],"darkred",3],["line",[200,50,230,60],"darkred",2],["line",[44,120,60,116],"darkred",2]]},"ew_passage":{"name":"East-West Passage","dark":true,"desc":"This is a narrow east-west passageway. There is a narrow stairway leading down at the north end of the room. [The rest of the Great Underground Empire lies beyond this excerpt.]","exits":{"west":"troll_room","east":{"msg":"Rubble blocks the way. (The full ZORK I continues from here.)"},"down":{"msg":"The stairway is choked with debris. (The full ZORK I continues from here.)"},"north":{"msg":"The stairway is choked with debris. (The full ZORK I continues from here.)"}},"art":[["tunnel","stone",7]]},"east_of_chasm":{"name":"East of Chasm","dark":true,"desc":"You are on the east edge of a chasm, the bottom of which cannot be seen. A narrow passage goes north, and the path you are on continues to the east.","exits":{"north":"cellar","east":"gallery","down":{"msg":"The chasm probably leads straight to the infernal regions."},"west":{"msg":"The chasm probably leads straight to the infernal regions."}},"art":[["bg","darkstone"],["dither",0,0,256,192,"darkstone","black","sparse"],["poly",[0,192,0,60,60,70,100,192],"black"],["poly",[100,192,60,70,140,80,256,120,256,192],"stone","black"]]},"gallery":{"name":"Gallery","desc":"This is an art gallery. Most of the paintings have been stolen by vandals with exceptional taste. The vandals left through either the north or west exits.","exits":{"west":"east_of_chasm","north":"studio"},"art":[["room","lightgray","darkred","white","black"],["wall","left",0.3,0.6,0.35,0.75,"none","gold"],["wall","right",0.3,0.6,0.35,0.75,"none","gold"],["wall","left",0.7,0.85,0.4,0.7,"none","gold"],["arch","right",0.85,"black","gray",0.15,0.6],["arch","left",0.1,"black","gray",0.12,0.6]]},"studio":{"name":"Studio","desc":"This appears to have been an artist's studio. The walls and floors are splattered with paints of 69 different colors. Strangely enough, nothing of value is hanging here. At the south end of the room is an open door (also covered with paint). A dark and narrow chimney leads up from a fireplace; although you might be able to get up it, it seems unlikely you could get back down.","exits":{"south":"gallery","up":{"to":"kitchen","if":"var:carried<=2","msg":"You can't get up there with what you're carrying.","say":"You climb up the narrow chimney, squeezing past the soot, and tumble out into..."}},"art":[["room","white","lightgray","white","black"],["rect",100,80,56,48,"darkstone","black"],["rect",108,88,40,40,"black"],["stars",60,"red",1,192],["stars",60,"blue",2,192],["stars",60,"green",3,192],["stars",60,"orange",4,192],["stars",50,"magenta",5,192],["door","left",0.4,"orange",true]]},"forest_w":{"name":"Forest","desc":"This is a forest, with trees in all directions. To the east, there appears to be sunlight.","exits":{"east":"west_of_house","north":"forest_path","south":"forest_s","west":{"msg":"You would need a machete to go further west."}},"art":[["gradient",0,192,"darkgreen","black"],["forest",60,"darkgreen",5,18],["forest",110,"moss",6,12],["glow",250,100,60,"yellow",0.3],["ground",170,"darkbrown"]]},"forest_s":{"name":"Forest","desc":"This is a dimly lit forest, with large trees all around.","exits":{"north":"south_of_house","west":"forest_w","east":"clearing_e","south":{"msg":"Storm-tossed trees block your way."}},"art":[["gradient",0,192,"darkgreen","black"],["forest",60,"darkgreen",15,18],["forest",110,"moss",16,12],["ground",170,"darkbrown"]]},"forest_path":{"name":"Forest Path","desc":"This is a path winding through a dimly lit forest. The path heads north-south here. One particularly large tree with some low branches stands at the edge of the path.","exits":{"south":"north_of_house","north":"clearing_n","up":"up_a_tree","east":"forest_s","west":"forest_w"},"art":[["gradient",0,120,"sky","darkgreen"],["forest",90,"darkgreen",21,14],["ground",112,"moss"],["path","tan",112,120,12],["rect",196,40,18,140,"brown","black"],["line",[205,100,170,80],"brown",5],["line",[205,70,240,50],"brown",5],["circle",205,30,40,"darkgreen"],["circle",170,50,22,"darkgreen"]]},"up_a_tree":{"name":"Up a Tree","desc":"You are about 10 feet above the ground nestled among some large branches. The nearest branch above you is above your reach.","exits":{"down":"forest_path","up":{"msg":"You cannot climb any higher."}},"art":[["bg","sky"],["circle",40,40,60,"darkgreen"],["circle",220,30,70,"darkgreen"],["circle",128,0,50,"moss"],["line",[0,150,120,140,256,120],"brown",10],["line",[60,192,90,144],"brown",12],["line",[180,192,200,128],"brown",8],["ellipse",140,136,22,9,"darkbrown","brown"],["line",[122,134,158,138],"tan"],["line",[124,138,156,132],"tan"]]},"clearing_n":{"name":"Clearing","desc":"You are in a clearing, with a forest surrounding you on all sides. A path leads south.","exits":{"south":"forest_path","east":"forest_s","west":"forest_w","north":{"msg":"The forest becomes impenetrable to the north."},"down":{"to":"grating_room","door":"grating","if":"flag:leaves_moved","msg":"You can't go that way."}},"art":[["gradient",0,110,"sky","white"],["forest",90,"darkgreen",41,18],["ground",110,"grass"],["if","!flag:leaves_moved",[["ellipse",128,160,40,12,"orange"],["dither",88,150,80,20,"orange","brown","sparse"]],[["if","open:grating",[["grate",108,150,40,18,"gray"],["rect",110,152,36,14,"black"]],[["grate",108,150,40,18,"gray"]]],["ellipse",190,170,20,6,"orange"]]]]},"clearing_e":{"name":"Clearing","desc":"You are in a small clearing in a well marked forest path that extends to the east and west.","exits":{"west":"behind_house","south":"forest_s","north":"forest_path","east":{"msg":"The path to the canyon is washed out. (The full ZORK I continues from here.)"}},"art":[["gradient",0,110,"sky","white"],["forest",92,"darkgreen",51,14],["ground",110,"grass"],["poly",[0,150,256,140,256,160,0,172],"tan"]]},"grating_room":{"name":"Grating Room","dark":true,"desc":["You are in a small room near the maze. There are twisty passages in the immediate vicinity.",{"if":"!open:grating","text":"Above you is a grating locked with a skull-and-crossbones lock."},{"if":"open:grating","text":"Above you is an open grating with sunlight pouring in."}],"exits":{"southwest":"maze_3","up":{"to":"clearing_n","door":"grating","do":[{"unset":"trap_barred"},{"set":"leaves_moved"},{"prop":"grating","key":"at","value":["clearing_n","grating_room"]},{"prop":"leaves","key":"at","value":null}]}},"art":[["cave","darkstone","black","stone",61],["grate",104,4,48,20,"gray"],["if","open:grating",[["rect",106,6,44,16,"sky"],["alpha",0.3],["poly",[104,24,152,24,190,192,66,192],"yellow"],["alpha",1]]],["skull",128,30,3,"white"]]},"maze_1":{"name":"Maze","dark":true,"desc":"This is part of a maze of twisty little passages, all alike.","exits":{"east":"troll_room","north":"maze_2","south":"maze_1","west":"maze_3","up":"maze_2"},"art":[["tunnel","darkstone",5],["poly",[0,40,40,70,40,140,0,170],"black","darkstone"],["poly",[256,40,216,70,216,140,256,170],"black","darkstone"]]},"maze_2":{"name":"Maze","dark":true,"desc":"This is part of a maze of twisty little passages, all alike. A skeleton, probably the remains of a luckless adventurer, lies here.","exits":{"south":"maze_1","down":"maze_1","north":"maze_2","east":"maze_2","west":"maze_1"},"art":[["tunnel","darkstone",5],["skull",100,168,7,"bone"],["bones",140,176,10,"bone",77]]},"maze_3":{"name":"Maze","dark":true,"desc":"This is part of a maze of twisty little passages, all alike.","exits":{"east":"maze_1","north":"maze_3","south":"maze_1","northeast":"grating_room","west":"maze_3"},"art":[["tunnel","darkstone",5],["poly",[256,30,210,60,210,130,256,160],"black","darkstone"]]}},"items":{"house":{"name":"white house","nouns":["house","home"],"adj":["white","colonial"],"at":["west_of_house","north_of_house","south_of_house","behind_house"],"scenery":true,"desc":"The house is a beautiful colonial house which is painted white. It is clear that the owners must have been extremely wealthy.","on":{"enter":"You can't enter the house that way."}},"front_door":{"name":"front door","nouns":["door","boards"],"adj":["front","boarded"],"at":"west_of_house","scenery":true,"desc":"The door is boarded and you can't remove the boards.","on":{"open,pull,break":"The door cannot be opened."}},"mailbox":{"name":"small mailbox","nouns":["mailbox","box"],"adj":["small"],"at":"west_of_house","fixed":true,"container":true,"open":false,"here":"There is a small mailbox here.","fixedMsg":"It is securely anchored.","art":[["rect",-2,-2,4,2,"none"]]},"leaflet":{"name":"leaflet","nouns":["leaflet","mail","booklet"],"at":"mailbox","desc":"\"WELCOME TO ZORK!\"","text":"\"WELCOME TO ZORK!\n\nZORK is a game of adventure, danger, and low cunning. In it you will explore some of the most amazing territory ever seen by mortals. No computer should be without one!\""},"window":{"name":"small window","nouns":["window"],"adj":["small","kitchen"],"at":["behind_house","kitchen"],"scenery":true,"open":false,"desc":[{"if":"open:window","text":"The window is open.","else":"The window is slightly ajar, but not enough to allow entry."}],"openMsg":"With great effort, you open the window far enough to allow entry."},"kitchen_table":{"name":"kitchen table","nouns":["table"],"adj":["kitchen"],"at":"kitchen","scenery":true,"container":true,"surface":true},"sack":{"name":"brown sack","nouns":["sack","bag"],"adj":["brown","elongated"],"at":"kitchen_table","container":true,"open":false,"desc":"An elongated brown sack, smelling of hot peppers.","art":[["poly",[-5,0,5,0,4,-12,-4,-12],"brown","darkbrown"]]},"lunch":{"name":"lunch","nouns":["lunch","sandwich","food"],"adj":["hot","pepper"],"article":"a","at":"sack","edible":true,"desc":"A hot pepper sandwich.","eatMsg":"Thank you very much. It really hit the spot."},"garlic":{"name":"clove of garlic","nouns":["garlic","clove"],"at":"sack","edible":true,"eatMsg":"What the heck! You won't make friends this way, but nobody around here is too friendly anyhow. Gulp!"},"bottle":{"name":"glass bottle","nouns":["bottle"],"adj":["glass","clear"],"at":"kitchen_table","container":true,"open":false,"transparent":true,"desc":"A clear glass bottle.","art":[["poly",[-3,0,3,0,3,-8,1,-10,1,-13,-1,-13,-1,-10,-3,-8],"cyan","black"]]},"water":{"name":"quantity of water","nouns":["water"],"at":"bottle","drinkable":true,"drinkMsg":"Thank you very much. I was rather thirsty (from all this talking, probably).","on":{"take":{"do":"The water slips through your fingers.","if":"!at:water:bottle"}},"scenery":true},"trophy_case":{"name":"trophy case","nouns":["case"],"adj":["trophy"],"at":"living_room","scenery":true,"container":true,"open":false,"transparent":true,"desc":"The trophy case is securely fastened to the wall."},"sword":{"name":"sword","nouns":["sword","blade"],"adj":["elvish","antique"],"at":"living_room","here":"Above the trophy case hangs an elvish sword of great antiquity.","desc":"It's an elvish sword of great antiquity. Its blade is etched with runes.","art":[["line",[0,-42,0,-6],"silver",2],["line",[-5,-10,5,-10],"gold",2],["line",[0,-6,0,0],"darkbrown",2]],"artAt":[36,92]},"lamp":{"name":"brass lantern","nouns":["lamp","lantern","light"],"adj":["brass","battery-powered"],"at":"living_room","lightable":true,"lit":false,"here":"A battery-powered brass lantern is on the trophy case.","lightMsg":"The brass lantern is now on.","outMsg":"The brass lantern is now off.","desc":[{"if":"lit:lamp","text":"The lamp is on.","else":"The lamp is turned off."}],"art":[["rect",-4,-12,8,10,"gold","black"],["rect",-3,-2,6,2,"gold"],["arc",0,-12,4,180,360,"gold",1.5],["if","lit:lamp",[["glow",0,-7,14,"yellow",0.7]]]],"artAt":[50,120]},"rug":{"name":"oriental rug","nouns":["rug","carpet"],"adj":["oriental","large"],"at":"living_room","scenery":true,"desc":[{"if":"flag:rug_moved","text":"The rug lies to one side of the room.","else":"A large oriental rug, in the center of the room."}],"on":{"push,pull,take,lift":{"if":"!flag:rug_moved","do":["With a great effort, the rug is moved to one side of the room, revealing the dusty cover of a closed trap door.",{"set":"rug_moved","show":"trap_door"},{"exit":"living_room","dir":"down","to":{"to":"cellar","door":"trap_door"}}],"else":["Having moved the carpet previously, you find it impossible to move it again."]},"search":{"if":"!flag:rug_moved","do":"Underneath the rug is a closed trap door. As you drop the corner of the rug, the trap door is once again concealed from view.","else":"There is nothing under the rug now."}}},"trap_door":{"name":"trap door","nouns":["trapdoor","trap-door","door"],"adj":["trap","dusty"],"at":["living_room","cellar"],"scenery":true,"hidden":true,"open":false,"openMsg":"The door reluctantly opens to reveal a rickety staircase descending into darkness.","on":{"open":{"room":"cellar","if":"flag:trap_barred","do":"The door is locked from above."}}},"gothic_door":{"name":"wooden door","nouns":["door","lettering"],"adj":["wooden","gothic","strange"],"at":"living_room","scenery":true,"desc":"The engravings translate to \"This space intentionally left blank.\"","on":{"open,pull,break":"The door cannot be opened."}},"attic_table":{"name":"table","at":"attic","scenery":true,"container":true,"surface":true},"knife":{"name":"nasty knife","nouns":["knife","blade"],"adj":["nasty","nasty-looking"],"at":"attic_table","desc":"A nasty-looking knife.","art":[["line",[-6,-2,6,-2],"silver",2],["line",[-10,-2,-6,-2],"darkbrown",3]]},"rope":{"name":"rope","nouns":["rope","coil"],"adj":["large"],"at":"attic","here":"A large coil of rope is lying in the corner.","art":[["ellipse",0,-4,10,5,null,"tan",2],["ellipse",0,-4,6,3,null,"tan",2]],"artAt":[60,160]},"troll":{"name":"troll","nouns":["troll"],"adj":["nasty"],"at":"troll_room","fixed":true,"here":"A nasty-looking troll, brandishing a bloody axe, blocks all passages out of the room.","fixedMsg":"The troll spits in your face, grunting \"Better luck next time\" in a rather barbarous accent.","desc":"A nasty-looking troll, brandishing a bloody axe. He looks at you with undisguised hostility.","art":[["ellipse",0,-36,18,26,"olive","black"],["circle",0,-68,11,"olive","black"],["circle",-4,-70,2,"red"],["circle",4,-70,2,"red"],["rect",-14,-14,8,14,"olive","black"],["rect",6,-14,8,14,"olive","black"],["line",[16,-40,34,-70],"darkbrown",3],["poly",[28,-78,42,-70,34,-60],"silver","darkred"]],"artAt":[128,176],"on":{"give,throw":{"do":["The troll, who is remarkably coordinated, catches it and eats it hungrily. Poor troll, he dies from an indigestible meal... no wait, he just burps and looks hungrier."]},"say":"The troll isn't much of a conversationalist."}},"axe":{"name":"bloody axe","nouns":["axe","ax"],"adj":["bloody"],"at":null,"desc":"A bloody axe.","art":[["line",[-10,0,8,-16],"darkbrown",2],["poly",[4,-22,14,-14,8,-10],"silver","darkred"]]},"egg":{"name":"jewel-encrusted egg","nouns":["egg"],"adj":["jewel-encrusted","jeweled","encrusted","large"],"at":"nest","points":5,"deposit":{"in":"trophy_case","points":5},"desc":"The egg is covered with fine gold inlay, and ornamented in lapis lazuli and mother-of-pearl. Unlike most eggs, this one is hinged and closed with a delicate looking clasp. The egg appears extremely fragile.","art":[["ellipse",0,-7,6,7,"gold","black"],["circle",-2,-8,1.5,"blue"],["circle",2,-5,1.5,"blue"],["circle",1,-11,1,"white"]],"on":{"open":"You have neither the tools nor the expertise."}},"nest":{"name":"bird's nest","nouns":["nest"],"adj":["bird's","small"],"at":"up_a_tree","container":true,"here":"Beside you on the branch is a small bird's nest.","art":[],"artAt":[140,136]},"tree":{"name":"large tree","nouns":["tree","branches","branch"],"adj":["large","low"],"at":["forest_path","up_a_tree"],"scenery":true,"desc":"One particularly large tree with some low branches.","on":{"climb":{"room":"forest_path","do":[{"goto":"up_a_tree"}]}}},"painting":{"name":"painting","nouns":["painting","art","masterpiece","canvas"],"adj":["beautiful"],"at":"gallery","points":4,"deposit":{"in":"trophy_case","points":6},"here":"Fortunately, there is still one chance for you to be a vandal, for on the far wall is a painting of unparalleled beauty.","desc":"A painting of unparalleled beauty.","art":[["rect",-18,-26,36,26,"gold"],["rect",-15,-23,30,20,"sky"],["circle",-6,-14,5,"darkgreen"],["rect",-15,-10,30,7,"grass"],["circle",8,-18,3,"yellow"]],"artAt":[128,104]},"leaves":{"name":"pile of leaves","nouns":["leaves","pile","leaf"],"at":"clearing_n","fixed":true,"here":"On the ground is a pile of leaves.","on":{"push,pull,take,search,move":{"if":"!flag:leaves_moved","do":["In disturbing the pile of leaves, a grating is revealed.",{"set":"leaves_moved"},{"prop":"grating","key":"at","value":["clearing_n","grating_room"]}],"else":["The leaves are scattered everywhere now."]}}},"grating":{"name":"grating","nouns":["grating","grate","lock"],"adj":["skull-and-crossbones"],"at":"grating_room","scenery":true,"hidden":false,"open":false,"locked":true,"key":"skeleton_key","desc":[{"if":"in:clearing_n","text":"There is a grating securely fastened into the ground.","else":"A grating, locked with a skull-and-crossbones lock."}],"openMsg":"The grating opens to reveal trees above you.","on":{"unlock":{"room":"clearing_n","do":"You can't reach the lock from here."}}},"skeleton":{"name":"skeleton","nouns":["skeleton","bones","remains"],"at":"maze_2","scenery":true,"desc":"A skeleton, probably the remains of a luckless adventurer.","on":{"take,attack,push":"Disturbing the remains of the dead is bad luck."}},"coins":{"name":"leather bag of coins","nouns":["bag","coins","money"],"adj":["leather"],"at":"maze_2","points":10,"deposit":{"in":"trophy_case","points":5},"desc":"An old leather bag, bulging with coins.","art":[["poly",[-6,0,6,0,5,-8,2,-10,-2,-10,-5,-8],"brown","black"],["line",[-2,-10,2,-12],"tan"]]},"skeleton_key":{"name":"skeleton key","nouns":["key"],"adj":["skeleton"],"at":"maze_2","art":[["circle",-5,-3,2.5,null,"lightgray",1.5],["line",[-3,-3,6,-3],"lightgray",1.5],["line",[4,-3,4,0],"lightgray",1.5]]},"rusty_knife":{"name":"rusty knife","nouns":["knife"],"adj":["rusty"],"at":"maze_2","desc":"A rusty knife. It seems to want to be held.","art":[["line",[-6,-2,6,-2],"rust",2],["line",[-10,-2,-6,-2],"darkbrown",3]]}},"actions":[{"verb":"attack","noun":"troll","if":"flag:troll_dead","do":"There's no troll left to attack."},{"verb":"attack","noun":"troll","if":{"any":["has:sword","has:knife","has:rusty_knife","has:axe"]},"do":[{"if":"has:sword","then":[{"var":"hitroll","value":0},{"random":[[{"var":"hitroll","value":1}],[{"var":"hitroll","value":1}],[{"var":"hitroll","value":0}]]}],"else":[{"var":"hitroll","value":0},{"random":[[{"var":"hitroll","value":1}],[{"var":"hitroll","value":0}],[{"var":"hitroll","value":0}]]}]},{"if":"var:hitroll==1","then":[{"var":"troll_hp","add":1},{"if":"var:troll_hp>=2","then":["The fatal blow strikes the troll square in the heart: He dies.\nAlmost as soon as the troll breathes his last breath, a cloud of sinister black fog envelops him, and when the fog lifts, the carcass has disappeared.",{"set":"troll_dead","destroy":"troll"},{"move":"axe","to":"here"}],"else":[{"random":["The troll is staggered, and drops to his knees.","A good slash, and it draws first blood!","The troll is battered into near unconsciousness - but struggles back to his feet."]}]}],"else":[{"random":["A good slash, but it misses the troll by a mile.","You charge, but the troll jumps nimbly aside.","The troll parries your blow with his axe.","Clang! Your blow bounces off the troll's axe."]}]}],"else":"Attacking the troll with your bare hands is suicidal."},{"verb":"take","noun":"water","if":"at:water:bottle","do":[{"if":"has:bottle","then":"You already have it, in the bottle.","else":"You can't carry water without a container. Try taking the bottle."}]},{"verb":"say","noun":["hello","sailor"],"do":"Nothing happens here."},{"verb":"say","noun":["odysseus","ulysses"],"do":"Wasn't he a sailor?"},{"verb":"pray","do":"If you pray enough, your prayers may be answered."},{"verb":"climb","noun":"tree","room":"up_a_tree","do":"You cannot climb any higher."},{"verb":"jump","room":"up_a_tree","do":[{"die":"In a feat of unaccustomed daring, you manage to land on your feet without killing yourself... no, wait. You land on your head. Ouch."}]},{"verb":"go","noun":"down","room":"living_room","if":"!flag:rug_moved","do":"You can't go that way."}],"events":[{"if":["in:living_room","flag:trap_closing"],"do":[{"unset":"trap_closing"}]},{"if":["in:cellar","!flag:trap_used"],"do":["The trap door crashes shut, and you hear someone barring it.",{"set":["trap_used","trap_barred"]},{"prop":"trap_door","key":"open","value":false}]},{"if":["in:troll_room","!flag:troll_dead"],"do":[{"if":"var:troll_attacks>=0","then":[{"var":"troll_attacks","add":1}]},{"if":"var:troll_attacks>=2","then":[{"random":[["The troll swings his axe, but it misses."],["The axe sweeps past as you jump aside."],["The troll's axe barely misses your ear."],[{"var":"wounds","add":1},"The axe gets you right in the side. Ouch!"],[{"var":"wounds","add":1},"The flat of the troll's axe hits you delicately on the head, knocking you briefly senseless."]]},{"if":"var:wounds>=3","then":[{"die":"The troll's mighty blow drops you to your knees.\nThe troll lands a deadly blow. It appears that that last blow was too much for you. I'm afraid you are dead."}]}]}]},{"if":"!in:troll_room","do":[{"var":"troll_attacks","value":0}]},{"if":"dark","do":[{"var":"darkturns","add":1},{"if":["var:darkturns>=2","chance:60"],"then":[{"die":"Oh, no! You have walked into the slavering fangs of a lurking grue!"}]}]},{"if":"!dark","do":[{"var":"darkturns","value":0}]},{"if":["at:egg:trophy_case","at:painting:trophy_case","at:coins:trophy_case"],"once":true,"do":[{"win":"An almost inaudible voice whispers in your ear, \"Look to your treasures for the final secret.\"\n\nYou have gathered every treasure in this excerpt of the Great Underground Empire. The full ZORK I - with the thief, the dam, the Land of the Dead and nineteen treasures in all - is free to play and study under the MIT License."}]}]},"adventures/colossal-cave.json":{"format":"gta-1","id":"colossal-cave-excerpt","title":"COLOSSAL CAVE ADVENTURE","author":"After Will Crowther (1976) and Don Woods (1977). An illustrated excerpt: the surface, the upper cave and the Hall of the Mountain King.","theme":"phosphor","maxScore":70,"start":"road","intro":"Somewhere nearby is Colossal Cave, where others have found fortunes in treasure and gold, though it is rumored that some who enter are never seen again. Magic is said to work in the cave.\n\n[This excerpt has one treasure: bring the gold nugget back to the well house. Type HELP for instructions.]","help":"I know of places, actions, and things. Most of my vocabulary describes places and is used to move you there: try words like FOREST, BUILDING, DOWNSTREAM, ENTER, EAST, WEST, NORTH, SOUTH, UP, or DOWN. I know about a few special objects, like a black rod hidden in the cave. These objects can be manipulated using some of the action words that I know. Usually you will need to give both the object and action words, as in TAKE LAMP or LIGHT LAMP. Some magic words will work too.","ranks":[[0,"Rank Amateur"],[20,"Novice"],[40,"Experienced Adventurer"],[60,"Seasoned Adventurer"],[70,"Junior Master"]],"messages":{"dark":"It is now pitch dark. If you proceed you will likely fall into a pit.","noExit":"There is no way to go that direction.","dontKnowVerb":"I don't know that word."},"artLib":{"woods":[["gradient",0,120,"sky","white"],["forest",96,"darkgreen",7,16],["ground",120,"grass"]],"cavern":[["cave","darkstone","black","stone",3]]},"rooms":{"road":{"name":"End of Road","desc":"You are standing at the end of a road before a small brick building. Around you is a forest. A small stream flows out of the building and down a gully.","exits":{"east":"building","in":"building","west":"hill","up":"hill","south":"valley","down":"valley","north":"forest","upstream":"building"},"art":[["use","woods"],["path","gray",120,60,16],["rect",150,70,60,50,"red","black"],["dither",150,70,60,50,"red","darkred","brick"],["poly",[144,70,216,70,180,50],"darkgray","black"],["rect",172,92,14,28,"black"],["poly",[180,120,190,120,120,192,90,192],"water"]]},"building":{"name":"Inside Building","desc":"You are inside a building, a well house for a large spring.","exits":{"west":"road","out":"road","downstream":"road"},"art":[["room","red","gray","darkgray","black"],["dither",72,40,112,88,"red","darkred","brick"],["texture","left","red","darkred","brick"],["texture","right","red","darkred","brick"],["ellipse",128,160,40,14,"water","lightgray",3],["ellipse",128,160,30,9,"cyan"],["door","left",0.5,"black",true]]},"hill":{"name":"Hill in Road","desc":"You have walked up a hill, still in the forest. The road slopes back down the other side of the hill. There is a building in the distance.","exits":{"east":"road","down":"road","west":"forest","north":"forest","south":"forest"},"art":[["use","woods"],["hills",140,"grass",4,20],["path","gray",100,80,6],["rect",40,92,14,10,"red","black"]]},"forest":{"name":"Forest","desc":"You are in open forest, with a deep valley to one side.","exits":{"east":"valley","down":"valley","north":"forest","west":"forest","south":"road"},"art":[["gradient",0,192,"darkgreen","black"],["forest",60,"darkgreen",8,16],["forest",110,"moss",9,10],["ground",170,"darkbrown"]]},"valley":{"name":"In a Valley","desc":"You are in a valley in the forest beside a stream tumbling along a rocky bed.","exits":{"north":"road","upstream":"road","east":"forest","west":"forest","up":"forest","south":"slit","downstream":"slit","down":"slit"},"art":[["use","woods"],["hills",110,"darkgreen",12,30],["poly",[100,120,140,120,200,192,40,192],"water"],["rocks",160,"stone",13,10]]},"slit":{"name":"Slit in Streambed","desc":"At your feet all the water of the stream splashes into a 2-inch slit in the rock. Downstream the streambed is bare rock.","exits":{"north":"valley","upstream":"valley","south":"depression","downstream":"depression","down":{"msg":"You don't fit through a two-inch slit!"}},"art":[["use","woods"],["rect",0,120,256,72,"stone"],["dither",0,120,256,72,"stone","darkstone","sparse"],["poly",[100,120,140,120,132,160,108,160],"water"],["line",[104,162,136,162],"black",2]]},"depression":{"name":"Outside Grate","desc":["You are in a 20-foot depression floored with bare dirt. Set into the dirt is a strong steel grate mounted in concrete. A dry streambed leads into the depression.",{"if":"open:grate","text":"The grate is open.","else":"The grate is locked."}],"exits":{"north":"slit","upstream":"slit","down":{"to":"below_grate","door":"grate"},"in":{"to":"below_grate","door":"grate"}},"art":[["use","woods"],["ellipse",128,160,120,40,"darkbrown"],["rect",96,146,64,28,"lightgray","black"],["if","open:grate",[["rect",102,150,52,20,"black"],["grate",160,140,40,18,"gray"]],[["grate",102,150,52,20,"gray"]]]]},"below_grate":{"name":"Below the Grate","desc":"You are in a small chamber beneath a 3x3 steel grate to the surface. A low crawl over cobbles leads inward to the west.","exits":{"up":{"to":"depression","door":"grate"},"out":{"to":"depression","door":"grate"},"west":"cobble"},"onEnter":[{"if":"first","do":[{"score":15}]}],"art":[["use","cavern"],["grate",104,2,48,18,"gray"],["if","open:grate",[["rect",106,4,44,14,"sky"]]],["alpha",0.25],["poly",[104,20,152,20,180,192,76,192],"yellow"],["alpha",1]]},"cobble":{"name":"In Cobble Crawl","desc":"You are crawling over cobbles in a low passage. There is a dim light at the east end of the passage.","exits":{"east":"below_grate","west":"debris"},"art":[["bg","darkstone"],["poly",[0,0,256,0,256,70,0,70],"black"],["rect",0,120,256,72,"stone"],["dither",0,120,256,72,"stone","darkgray"],["glow",250,100,40,"yellow",0.3]]},"debris":{"name":"In Debris Room","dark":true,"desc":"You are in a debris room filled with stuff washed in from the surface. A low wide passage with cobbles becomes plugged with mud and debris here, but an awkward canyon leads upward and west. A note on the wall says, \"MAGIC WORD XYZZY\".","exits":{"east":"cobble","up":"canyon","west":"canyon"},"art":[["use","cavern"],["rocks",150,"darkbrown",22,12],["text",30,60,"XYZZY","white",10]]},"canyon":{"name":"Sloping E/W Canyon","dark":true,"desc":"You are in an awkward sloping east/west canyon.","exits":{"east":"debris","down":"debris","west":"bird_chamber","up":"bird_chamber"},"art":[["bg","black"],["poly",[0,0,110,0,60,192,0,192],"darkstone","stone"],["poly",[256,0,146,0,196,192,256,192],"darkstone","stone"],["poly",[60,192,196,192,150,60,106,60],"stone"]]},"bird_chamber":{"name":"Orange River Chamber","dark":true,"desc":"You are in a splendid chamber thirty feet high. The walls are frozen rivers of orange stone. An awkward canyon and a good passage exit from east and west sides of the chamber.","exits":{"east":"canyon","west":"small_pit"},"art":[["bg","orange"],["dither",0,0,256,192,"orange","rust","lines"],["poly",[60,192,196,192,170,120,86,120],"stone"],["arch","back",0.5,"black","rust",0.3,0.6]]},"small_pit":{"name":"At Top of Small Pit","dark":true,"desc":"At your feet is a small pit breathing traces of white mist. An east passage ends here except for a small crack leading on. Rough stone steps lead down the pit.","exits":{"east":"bird_chamber","down":"hall_of_mists","west":{"msg":"The crack is far too small for you to follow."}},"art":[["use","cavern"],["ellipse",128,160,50,16,"black","stone"],["alpha",0.4],["ellipse",128,150,40,10,"white"],["alpha",1]]},"hall_of_mists":{"name":"In Hall of Mists","dark":true,"desc":"You are at one end of a vast hall stretching forward out of sight to the west. There are openings to either side. Nearby, a wide stone staircase leads downward. The hall is filled with wisps of white mist swaying to and fro almost as if alive. A cold wind blows up the staircase. There is a passage at the top of a dome behind you.","exits":{"up":{"to":"small_pit","if":"!has:nugget","msg":"The dome is unclimbable."},"south":"nugget_room","left":"nugget_room","down":"mountain_king","west":{"msg":"A wide fissure blocks the way west. (The rest of the cave lies beyond this excerpt.)"}},"art":[["bg","black"],["tunnel","darkstone",5],["alpha",0.35],["ellipse",60,120,60,12,"white"],["ellipse",180,90,70,10,"white"],["ellipse",120,150,80,8,"white"],["alpha",1],["stairs","down","lightgray",0.5]]},"nugget_room":{"name":"Low Room","dark":true,"desc":"This is a low room with a crude note on the wall. The note says, \"You won't get it up the steps\".","exits":{"north":"hall_of_mists","out":"hall_of_mists"},"art":[["bg","darkstone"],["poly",[0,0,256,0,256,60,0,80],"black"],["rect",0,140,256,52,"stone"],["text",70,100,"YOU WON'T GET IT UP THE STEPS","white",7]]},"mountain_king":{"name":"Hall of the Mountain King","dark":true,"desc":"You are in the Hall of the Mountain King, with passages off in all directions.","exits":{"up":"hall_of_mists","east":"hall_of_mists","north":{"to":"y2","if":"flag:snake_gone","msg":"You can't get by the snake."},"south":{"if":"flag:snake_gone","msg":"You can't get by the snake."},"west":{"if":"flag:snake_gone","msg":"You can't get by the snake."}},"art":[["use","cavern"],["arch","left",0.5,"black","stone",0.25,0.5],["arch","right",0.5,"black","stone",0.25,0.5]]},"y2":{"name":"At \"Y2\"","dark":true,"desc":"You are in a large room, with a passage to the south, a passage to the west, and a wall of broken rock to the east. There is a large \"Y2\" on a rock in the room's center.","exits":{"south":"mountain_king","west":{"msg":"The passage west is blocked by fallen rock. (This excerpt ends here.)"},"east":{"msg":"The wall of broken rock is impassable."}},"art":[["use","cavern"],["poly",[100,170,156,170,150,130,106,130],"lightgray","black"],["text",116,158,"Y2","black",18]]}},"items":{"keys":{"name":"set of keys","nouns":["keys","key"],"at":"building","here":"There are some keys on the ground here.","art":[["circle",0,-4,3,null,"lightgray",1.5],["line",[2,-3,8,0],"lightgray",1.5],["line",[-2,-3,-7,0],"gold",1.5]]},"lamp":{"name":"brass lantern","nouns":["lamp","lantern","headlamp"],"adj":["brass","shiny"],"at":"building","lightable":true,"lit":false,"here":"There is a shiny brass lamp nearby.","lightMsg":"Your lamp is now on.","outMsg":"Your lamp is now off.","art":[["rect",-4,-12,8,10,"gold","black"],["arc",0,-12,4,180,360,"gold",1.5],["if","lit:lamp",[["glow",0,-7,14,"yellow",0.7]]]]},"food":{"name":"tasty food","nouns":["food","rations"],"adj":["tasty"],"article":"some","at":"building","edible":true,"here":"There is food here.","eatMsg":"Thank you, it was delicious!","art":[["rect",-5,-4,10,4,"tan","brown"]]},"bottle":{"name":"small bottle","nouns":["bottle","water"],"adj":["small"],"at":"building","here":"There is a bottle of water here.","on":{"drink":"The bottle of water is now empty. You were thirsty."},"art":[["poly",[-3,0,3,0,3,-8,1,-10,1,-13,-1,-13,-1,-10,-3,-8],"cyan","black"]]},"spring":{"name":"spring","nouns":["spring","stream","water"],"at":["building","road","valley","slit"],"scenery":true,"desc":"Cold, clear water.","on":{"drink":"You have taken a drink from the stream. The water tastes strongly of minerals, but is not unpleasant. It is extremely cold."}},"building_s":{"name":"building","nouns":["building","house","wellhouse"],"adj":["brick","small","well"],"at":["road","hill"],"scenery":true,"goes":"in","desc":"A small brick building."},"grate":{"name":"steel grate","nouns":["grate","grating"],"adj":["steel","strong"],"at":["depression","below_grate"],"scenery":true,"open":false,"locked":true,"key":"keys","lockedMsg":"The grate is locked.","unlockMsg":"The grate is now unlocked.","desc":"It just looks like an ordinary grate mounted in concrete."},"cage":{"name":"wicker cage","nouns":["cage"],"adj":["wicker","small"],"at":"cobble","container":true,"transparent":true,"here":"There is a small wicker cage discarded nearby.","art":[["rect",-7,-12,14,12,"none","tan"],["line",[-3,-12,-3,0],"tan"],["line",[1,-12,1,0],"tan"],["line",[5,-12,5,0],"tan"],["arc",0,-12,7,180,360,"tan"]]},"rod":{"name":"black rod","nouns":["rod","star"],"adj":["black","rusty"],"at":"debris","here":"A three foot black rod with a rusty star on an end lies nearby.","art":[["line",[-14,0,14,-8],"darkgray",2],["circle",14,-8,2,"rust"]],"on":{"wave":"Nothing happens. (Perhaps it would do something at the fissure - but that lies beyond this excerpt.)"}},"bird":{"name":"little bird","nouns":["bird"],"adj":["little","cheerful"],"at":"bird_chamber","here":"A cheerful little bird is sitting here singing.","art":[["ellipse",0,-5,5,4,"yellow","black"],["circle",4,-9,3,"yellow","black"],["poly",[6,-9,10,-8,6,-7],"orange"]],"desc":[{"if":"at:bird:cage","text":"The little bird is in the cage, looking unhappy.","else":"A cheerful little bird."}]},"nugget":{"name":"large gold nugget","nouns":["nugget","gold"],"adj":["large","sparkling"],"at":"nugget_room","points":10,"here":"There is a large sparkling nugget of gold here!","art":[["poly",[-6,0,6,0,7,-5,2,-9,-4,-7],"gold","darkbrown"],["circle",2,-5,1,"white"]]},"snake":{"name":"huge green snake","nouns":["snake"],"adj":["huge","green","fierce"],"at":"mountain_king","fixed":true,"here":"A huge green fierce snake bars the way!","desc":"I wouldn't mess with it if I were you.","fixedMsg":"That's not something you can pick up.","art":[["line",[-50,0,-30,-10,-10,0,10,-10,30,0,40,-16],"green",6],["circle",42,-18,6,"green"],["circle",44,-20,1.5,"red"],["line",[48,-18,54,-16],"red"]],"artAt":[128,170],"on":{"attack":"Attacking the snake both doesn't work and is very dangerous."}},"note":{"name":"note","nouns":["note","wall","writing"],"at":["debris","nugget_room"],"scenery":true,"desc":"The note is scrawled on the wall.","text":[{"if":"in:debris","text":"\"MAGIC WORD XYZZY\"","else":"\"You won't get it up the steps\""}]}},"actions":[{"verb":"xyzzy","room":"building","do":[{"goto":"debris"}]},{"verb":"xyzzy","room":"debris","do":[{"goto":"building"}]},{"verb":"say","noun":"xyzzy","room":"building","do":[{"goto":"debris"}]},{"verb":"say","noun":"xyzzy","room":"debris","do":[{"goto":"building"}]},{"verb":"xyzzy","do":"Nothing happens."},{"verb":"plugh","room":"building","if":"visited:y2","do":[{"goto":"y2"}]},{"verb":"plugh","room":"y2","do":[{"goto":"building"}]},{"verb":"say","noun":"plugh","room":"y2","do":[{"goto":"building"}]},{"verb":"plugh","do":"Nothing happens."},{"verb":"say","noun":"plugh","do":"Nothing happens."},{"verb":"take,catch","noun":"bird","if":"at:bird:cage","do":"You already have the little bird. If you take it out of the cage it will likely fly away from you."},{"verb":"take,catch","noun":"bird","if":"here:bird","do":[{"if":"has:rod","then":"As you approach the bird, it becomes disturbed and you cannot catch it.","else":[{"if":"has:cage","then":["You catch the bird in the wicker cage.",{"move":"bird","to":"cage"},{"if":"!flag:bird_scored","then":[{"set":"bird_scored","score":10}]}],"else":"You can catch the bird, but you cannot carry it."}]}]},{"verb":"drop,free","noun":"bird","if":"at:bird:cage","do":[{"if":"here:snake","then":["The little bird attacks the green snake, and in an astounding flurry drives the snake away.",{"destroy":"snake","set":"snake_gone","score":15},{"move":"bird","to":"here"}],"else":["The little bird flies free.",{"move":"bird","to":"here"}]}]},{"verb":"attack","noun":"bird","do":"Oh, leave the poor unhappy bird alone."},{"verb":"go","noun":["building","house"],"room":"road","do":[{"goto":"building"}]},{"verb":"go","noun":["building","house"],"room":"hill","do":[{"goto":"road"}]},{"verb":"go","noun":"forest","room":["road","hill","valley"],"do":[{"goto":"forest"}]}],"events":[{"if":"dark","do":[{"var":"darkturns","add":1},{"if":["var:darkturns>=2","chance:35"],"then":[{"die":"You fell into a pit and broke every bone in your body!"}]}]},{"if":"!dark","do":[{"var":"darkturns","value":0}]},{"if":"at:nugget:building","once":true,"do":[{"score":20},{"win":"You have brought the gold nugget safely back to the well house. Deep below, the Hall of the Mountain King keeps its other secrets - for now.\n\nThe full Colossal Cave holds fifteen treasures, a pirate, a dragon and a troll bridge. Its source has been freely shared since 1977."}]}],"directions":{"downstream":"downstream","upstream":"upstream","left":"left","right":"right"}},"adventures/st-hilarion.json":{"format":"gta-1","id":"st-hilarion","title":"THE ABBEY OF ST. HILARION","author":"An original gothic adventure for this engine, in the spirit of the Mark Data Products classics","theme":"coco","maxScore":100,"maxCarry":8,"start":"road","intro":"The year is 1751. Word has reached the Bishop that the brothers of St. Hilarion's have fallen silent, and that strange lights burn beneath their chapel at night. No one sent to investigate has returned.\n\nNow it is your turn. Somewhere within the monastery lies the source of the black magic. Find it. Destroy it.\n\n(Type HELP for instructions.)","help":"Use two-word commands like GO NORTH (or N), GET CANDLE, LIGHT CANDLE, OPEN CABINET, READ BOOK, PUSH STATUE. You can also try longer ones like UNLOCK DOOR WITH KEY or POUR WATER ON PENTAGRAM. INVENTORY (I) lists what you carry. SAVE, RESTORE, UNDO and SCORE work at any time. Some places are dark: you'll want a light.","ranks":[[0,"Novice"],[20,"Pilgrim"],[45,"Acolyte"],[70,"Exorcist"],[100,"Saint"]],"messages":{"dark":"It is too dark to see. Cold air moves against your face, and something nearby is breathing.","noExit":"You can't go that way.","won":"*** THE BLACK MAGIC IS DESTROYED ***"},"colors":{"blood":"#8a0a0a","ember":"#ff3a1a"},"darkArt":[["bg","black"],["circle",120,96,1.5,"ember"],["circle",134,96,1.5,"ember"]],"artLib":{"nightsky":[["gradient",0,120,"night","darkred"],["stars",30,"buff",3,70],["moon",210,26,9,"buff"],["circle",214,23,8,"night"]],"arches_right":[["arch","right",0.25,"night","darkstone",0.2,0.55],["arch","right",0.6,"night","darkstone",0.2,0.55]],"arches_left":[["arch","left",0.25,"night","darkstone",0.2,0.55],["arch","left",0.6,"night","darkstone",0.2,0.55]],"sigils":[["pentagram",30,70,10,"blood"],["line",[220,60,236,90,214,82,240,70],"blood",2]]},"rooms":{"road":{"name":"Road before the monastery","desc":"You stand on a rutted road at dusk. North, behind a high stone wall, the black bulk of St. Hilarion's monastery rises against a blood-red sky. A crow watches you from a dead tree. An iron gate is set into the wall.","exits":{"north":{"to":"gatehouse","door":"gate"},"south":{"msg":"You've come too far to turn back now."}},"art":[["use","nightsky"],["rect",20,92,216,30,"darkstone"],["dither",20,92,216,30,"darkstone","black","brick"],["rect",92,52,64,44,"darkstone"],["poly",[88,52,160,52,124,26],"black"],["rect",162,30,18,66,"darkstone"],["poly",[160,30,182,30,171,8],"black"],["rect",120,64,8,14,"ember"],["rect",168,44,5,8,"ember"],["ground",120,"darkbrown"],["path","tan",120,130,40],["if","open:gate",[["rect",104,98,48,22,"black"],["gate",104,98,48,22,"gray",true]],[["gate",104,98,48,22,"gray"]]],["line",[36,170,38,120,30,96],"darkbrown",4],["line",[37,132,54,112,62,112],"darkbrown",2],["line",[33,110,18,92],"darkbrown",2],["poly",[56,108,64,104,70,107,63,110],"black"]]},"gatehouse":{"name":"Gatehouse","desc":"A crumbling gatehouse. Faded frescoes of saints peel from the walls; every one of their eyes has been scratched out. A notice is nailed beside the arch. The courtyard lies north, the road south.","exits":{"north":"courtyard","south":{"to":"road","door":"gate"}},"art":[["room","stone","darkstone","darkgray","black"],["arch","back",0.5,"night","darkstone",0.42,0.7],["wall","left",0.3,0.7,0.35,0.78,"tan","brown"],["wall","right",0.3,0.7,0.35,0.78,"tan","brown"],["wall","left",0.45,0.55,0.62,0.7,"skin"],["wall","right",0.45,0.55,0.62,0.7,"skin"],["wall","left",0.75,0.9,0.38,0.55,"buff","black"],["stars",6,"buff",41,60]]},"courtyard":{"name":"Courtyard","desc":["A weed-choked courtyard. In its center stands an old stone well with a rusted crank.",{"if":"flag:bucket_up","text":"A dripping bucket hangs at the top of the well."},"The chapel looms to the north, a cloister walk opens east, and a gap in the hedge leads west into a garden. The gatehouse is south."],"exits":{"north":"nave","east":"cloister","west":"garden","south":"gatehouse"},"art":[["gradient",0,112,"night","darkblue"],["stars",25,"white",9,60],["rect",78,28,100,84,"darkstone"],["poly",[74,28,182,28,128,4],"black"],["circle",128,52,11,"blood","black",2],["line",[128,41,128,63],"black"],["line",[117,52,139,52],"black"],["poly",[116,112,116,86,128,76,140,86,140,112],"black"],["rect",196,62,60,50,"stone"],["poly",[204,112,204,82,212,74,220,82,220,112],"black"],["poly",[230,112,230,82,238,74,246,82,246,112],"black"],["rect",0,70,58,42,"darkgreen"],["dither",0,70,58,42,"darkgreen","moss"],["rect",22,84,14,28,"black"],["ground",112,"moss"],["dither",0,112,256,80,"moss","darkgreen","sparse"],["well",128,176,22,"stone"],["if","flag:bucket_up",[["rect",121,126,14,10,"wood","black"],["line",[128,126,128,126,128,128],"buff"]]]]},"garden":{"name":"Herb garden","desc":"The monks' herb garden has run wild. Nightshade and wolfsbane choke the beds. A tool shed sags to the west, and a rusted gate in the north wall leads to the cemetery. The courtyard is east.","exits":{"east":"courtyard","west":"shed","north":"cemetery"},"art":[["use","nightsky"],["rect",0,70,256,40,"darkstone"],["dither",0,70,256,40,"darkstone","black","brick"],["gate",150,76,36,34,"rust"],["poly",[6,112,6,64,30,48,60,64,60,112],"wood","black"],["rect",24,80,14,32,"black"],["ground",110,"darkgreen"],["dither",70,130,70,30,"darkgreen","purple"],["dither",160,140,90,40,"darkgreen","olive"],["dither",20,160,100,30,"moss","purple","sparse"],["circle",90,138,2,"purple"],["circle",120,145,2,"purple"],["circle",200,150,2,"yellow"],["circle",230,170,2,"yellow"]]},"shed":{"name":"Tool shed","desc":"A cramped, leaning shed. Rotten rakes, cracked pots and coils of mouldy twine fill every corner. Daylight leaks through the boards. The garden is east.","exits":{"east":"garden","out":"garden"},"art":[["room","wood","darkbrown","darkbrown","black"],["dither",72,40,112,88,"wood","darkbrown","lines"],["line",[96,50,100,128],"tan",2],["line",[108,46,112,128],"tan",2],["poly",[90,46,106,46,104,52,92,52],"gray"],["circle",160,118,9,"rust","black"],["circle",172,120,7,"rust","black"],["door","right",0.45,"wood",true]]},"cemetery":{"name":"Cemetery","desc":["Leaning headstones crowd a sunken burial ground, and mist curls about your ankles.",{"if":"flag:dug","text":"One grave has been dug open.","else":"One grave, newer than the rest, has no name upon its stone - only a carved cross."},"The garden is south."],"exits":{"south":"garden"},"art":[["gradient",0,100,"night","darkblue"],["stars",30,"white",21,60],["moon",50,30,12,"buff"],["forest",100,"black",4,10],["ground",100,"darkgreen"],["poly",[20,150,20,120,28,114,36,120,36,150],"stone","black"],["poly",[60,130,60,108,67,103,74,108,74,130],"stone","black"],["poly",[196,140,198,112,206,106,214,112,214,142],"stone","black"],["cross",236,132,26,"stone"],["cross",170,116,16,"stone"],["poly",[112,146,112,112,128,102,144,112,144,146],"lightgray","black"],["cross",128,130,18,"darkstone"],["if","flag:dug",[["ellipse",128,168,34,12,"black"],["poly",[170,176,178,160,196,156,210,176],"darkbrown"]],[["ellipse",128,166,34,10,"darkbrown"]]],["alpha",0.35],["ellipse",70,178,90,10,"white"],["ellipse",200,186,80,8,"white"],["alpha",1]]},"nave":{"name":"Chapel nave","desc":"The nave of the chapel. Pews lie overturned and splintered, and someone has smeared strange sigils across the walls in something dark. Moonlight filters through a shattered rose window. A stone font stands beside the door. Stairs climb to the bell tower; the vestry is east, the sanctuary north, and the courtyard south.","exits":{"north":"sanctuary","east":"vestry","up":"belltower","south":"courtyard"},"art":[["room","stone","darkstone","darkgray","black"],["arch","back",0.5,"black","darkstone",0.3,0.45],["stainedglass","back",0.5,0.82,0.18,0.3],["stairs","up","stone",0.6,"left"],["door","right",0.5,"wood"],["use","sigils"],["poly",[70,150,120,146,122,152,72,158],"wood","black"],["poly",[140,160,196,152,200,158,144,168],"wood","black"],["poly",[96,170,104,160,150,182,140,188],"darkbrown","black"],["rect",22,160,14,24,"stone","black"],["ellipse",29,160,14,5,"stone","black"],["ellipse",29,160,10,3,"cyan"]]},"sanctuary":{"name":"Sanctuary","desc":["The sanctuary. The high altar has been stripped and defaced.",{"if":"flag:statue_moved","text":"The statue of the Virgin has been pushed aside, and a narrow stair leads down into darkness.","else":"Behind it, in a deep niche, stands a statue of the Virgin, her stone hands folded in prayer."},"The nave is south."],"exits":{"south":"nave"},"art":[["room","stone","darkstone","darkgray","black"],["window","left",0.5,0.6,"darkblue","black",0.16,0.4],["window","right",0.5,0.6,"darkblue","black",0.16,0.4],["arch","back",0.5,"darkstone","black",0.3,0.6],["if","flag:statue_moved",[["poly",[114,128,142,128,142,80,128,64,114,80],"black"],["line",[118,124,138,124],"gray"],["line",[120,118,136,118],"gray"],["line",[122,112,134,112],"gray"],["statue",158,128,46,"lightgray"]],[["statue",128,128,52,"lightgray"]]],["altar",96,168,64,26,"stone"],["line",[100,150,112,160,124,148],"blood",2]]},"vestry":{"name":"Vestry","desc":"A cramped vestry. Moth-eaten vestments hang from wooden pegs, and a tall cabinet stands against the far wall. The nave is west.","exits":{"west":"nave"},"art":[["room","wood","darkbrown","darkbrown","black"],["door","left",0.5,"wood",true],["rect",108,52,40,76,"darkbrown","black"],["if","open:cabinet",[["rect",112,56,32,68,"black"],["poly",[148,52,166,46,166,134,148,128],"darkbrown","black"]],[["line",[128,52,128,128],"black"],["rect",124,88,2,4,"gold"],["rect",130,88,2,4,"gold"]]],["poly",[192,60,204,58,210,120,186,124],"purple","black"],["poly",[218,54,230,52,236,124,212,128],"darkred","black"],["rect",196,54,4,4,"gold"],["rect",222,48,4,4,"gold"]]},"belltower":{"name":"Belfry","desc":"A dizzying climb ends in the belfry. A great bronze bell hangs from a beam above you, its rope trailing at your feet. Through the louvers you can see the whole dark monastery spread below - and a faint red glow seeping up from the ground beneath the chapel. Stairs lead down.","exits":{"down":"nave"},"art":[["bg","darkstone"],["gradient",0,192,"darkstone","black"],["rect",0,40,40,110,"night"],["rect",216,40,40,110,"night"],["line",[0,60,40,66],"wood",3],["line",[0,80,40,86],"wood",3],["line",[0,100,40,106],"wood",3],["line",[0,120,40,126],"wood",3],["line",[216,66,256,60],"wood",3],["line",[216,86,256,80],"wood",3],["line",[216,106,256,100],"wood",3],["line",[216,126,256,120],"wood",3],["rect",20,14,216,10,"wood","black"],["line",[128,24,128,36],"darkgray",3],["bell",128,120,90,"gold"],["line",[128,122,136,192],"tan",2],["glow",240,150,30,"ember",0.4]]},"cloister":{"name":"Cloister walk","desc":"A covered walk runs around a dead, grey garth. Doors lead north to the refectory, east to the monks' cells and south to the library. The courtyard is west.","exits":{"west":"courtyard","north":"refectory","east":"cells","south":"library"},"art":[["room","stone","darkstone","wood","black"],["use","arches_left"],["use","arches_right"],["door","back",0.5,"wood"],["dither",0,186,256,6,"darkstone","black"]]},"refectory":{"name":"Refectory","desc":"The refectory. A long oak table is laid for a meal that was never eaten: the bread has turned to stone and the wine has dried to a black crust in the jugs. The kitchen is east, the cloister south.","exits":{"east":"kitchen","south":"cloister"},"art":[["room","stone","wood","darkgray","black"],["window","back",0.3,0.6,"darkblue","black"],["window","back",0.7,0.6,"darkblue","black"],["door","right",0.55,"wood"],["poly",[70,178,186,178,160,130,96,130],"wood","black"],["circle",100,165,5,"lightgray","black"],["circle",156,165,5,"lightgray","black"],["circle",112,145,4,"lightgray","black"],["circle",144,145,4,"lightgray","black"],["rect",124,150,8,8,"tan","black"],["rect",104,136,5,8,"darkbrown","black"],["rect",148,136,5,8,"darkbrown","black"]]},"kitchen":{"name":"Kitchen","desc":"A soot-blackened kitchen. A great hearth gapes cold and empty in the far wall, and copper pots hang from hooks overhead. The refectory is west.","exits":{"west":"refectory"},"art":[["room","darkstone","darkstone","black","black"],["dither",72,40,112,88,"darkstone","black","sparse"],["poly",[96,128,96,80,160,80,160,128],"black","stone"],["rect",88,72,80,10,"stone","black"],["line",[108,126,148,126],"gray",2],["line",[112,122,140,120],"darkgray",2],["door","left",0.5,"wood",true],["circle",196,40,10,"orange","black"],["circle",222,34,12,"rust","black"],["circle",240,50,8,"orange","black"],["line",[196,30,196,0],"black"],["line",[222,22,222,0],"black"],["line",[240,42,240,0],"black"]]},"cells":{"name":"Monks' cells","desc":["A narrow passage lined with tiny bare cells where the brothers slept. In one, a straw pallet has been slashed open.",{"if":"open:abbot_door","text":"The heavy oak door to the north stands open.","else":"A heavy oak door to the north bears the abbot's seal."},"The cloister is west."],"exits":{"west":"cloister","north":{"to":"abbot","door":"abbot_door"}},"art":[["room","stone","darkstone","darkgray","black"],["door","left",0.2,"darkbrown",true,0.18],["door","left",0.62,"darkbrown",true,0.18],["door","right",0.2,"darkbrown",true,0.18],["door","right",0.62,"darkbrown",true,0.18],["if","open:abbot_door",[["door","back",0.5,"wood",true,0.34,0.8]],[["door","back",0.5,"wood",false,0.34,0.8],["circle",128,80,5,"red","black"]]],["poly",[30,178,70,168,76,176,36,188],"tan","black"],["line",[40,180,60,174],"darkbrown"]]},"abbot":{"name":"Abbot's quarters","desc":"The abbot lived far better than his brothers: a carved bed, a writing desk, and a great tapestry of the Last Judgment - in which, you notice, the damned appear to be smiling. The air smells faintly of sulphur. The cells lie south.","exits":{"south":"cells"},"art":[["room","wood","darkred","darkbrown","black"],["rect",84,48,88,68,"gold","black"],["dither",88,52,80,60,"darkred","gold"],["circle",128,72,10,"red"],["poly",[100,108,156,108,128,92],"black"],["poly",[176,150,236,136,256,160,256,192,196,192],"darkred","black"],["rect",226,110,8,40,"wood"],["table",20,150,50,30,"wood"],["glow",128,120,40,"ember",0.15]]},"library":{"name":"Library","desc":["Tall shelves of rotting books line the walls.",{"if":"here:glass_case","text":"In the middle of the room stands a glass case on a carved pedestal."},"A spiral stair leads up to the scriptorium. The cloister is north."],"exits":{"north":"cloister","up":"scriptorium"},"art":[["room","darkbrown","darkred","darkbrown","black"],["bookcase",74,42,108,84,"darkbrown"],["texture","left","darkbrown","darkred","lines"],["stairs","up","wood",0.55,"right"],["rect",116,150,24,30,"stone","black"],["rect",110,128,36,22,"none","cyan"],["alpha",0.25],["rect",110,128,36,22,"cyan"],["alpha",1],["if","at:liber:glass_case",[["rect",118,140,20,6,"white","gray"],["glow",128,142,20,"white",0.3]]]]},"scriptorium":{"name":"Scriptorium","desc":"Slanted writing desks fill the scriptorium beneath a tall window. Pots of dried ink and broken quills litter the floor. One desk is larger than the rest and has a drawer. A spiral stair leads down.","exits":{"down":"library"},"art":[["room","stone","wood","darkgray","black"],["window","back",0.5,0.65,"darkblue","black",0.3,0.5],["poly",[30,160,80,150,84,140,34,150],"wood","black"],["rect",34,160,4,20,"wood"],["rect",74,152,4,22,"wood"],["poly",[176,150,228,160,224,150,172,140],"wood","black"],["rect",180,150,4,22,"wood"],["rect",218,160,4,20,"wood"],["rect",100,130,56,8,"wood","black"],["rect",104,138,48,16,"darkbrown","black"],["if","open:drawer",[["rect",112,150,32,10,"black","wood"]],[["rect",126,144,4,3,"gold"]]],["line",[96,176,108,170],"white"],["line",[160,182,150,174],"white"],["circle",140,180,3,"black"]]},"crypt":{"name":"Crypt","dark":true,"desc":"The crypt. Stone coffins of long-dead abbots line the walls. Several lids have been pushed aside... from the inside. A low passage leads north; stairs climb up to the sanctuary.","exits":{"up":"sanctuary","north":"catacombs"},"art":[["room","darkstone","darkstone","black","black"],["arch","back",0.5,"black","stone",0.3,0.5],["poly",[6,186,60,160,70,168,16,192],"stone","black"],["poly",[20,150,56,136,64,140,28,156],"stone","black"],["poly",[250,186,196,160,186,168,240,192],"stone","black"],["poly",[236,150,200,136,192,140,228,156],"darkstone","black"],["poly",[190,152,204,146,210,150,196,156],"black"],["stairs","up","stone",0.3,"left"]]},"catacombs":{"name":"Catacombs","dark":true,"desc":["Narrow catacombs wind between niches stacked with skulls. The air is thick, and strangely warm.",{"if":"!flag:bats_gone","text":"From the north passage comes a dry, restless fluttering."},"Passages lead north and east; the crypt is south."],"exits":{"south":"crypt","east":"ossuary","north":{"to":"sanctum","if":["flag:bats_gone","has:crucifix"],"else":[{"if":"!flag:bats_gone","then":["A shrieking, flapping cloud of bats boils out of the north passage! Claws and leathery wings beat at your face, and you stagger back, half blinded."],"else":["You step toward the north passage, and a wave of pure malice hurls you back against the bones. Something down there knows you are coming - and you have no holy protection."]}]}},"art":[["tunnel","darkstone",6],["skull",30,60,6],["skull",44,60,6],["skull",30,80,6],["skull",44,80,6],["skull",212,60,6],["skull",226,60,6],["skull",212,80,6],["skull",226,80,6],["skull",60,100,4],["skull",196,100,4],["if","!flag:bats_gone",[["glow",128,90,24,"ember",0.3],["line",[118,86,122,82,126,86],"black",2],["line",[130,92,134,88,138,92],"black",2],["line",[112,96,116,93,120,96],"black",2]]]]},"ossuary":{"name":"Ossuary","dark":true,"desc":"An ossuary. The bones of generations of monks have been sorted with horrible neatness - skulls in one heap, thighbones stacked like firewood in another. The catacombs are west.","exits":{"west":"catacombs"},"art":[["cave","darkstone","black","darkstone",12],["bones",80,164,14,"bone",3],["bones",190,170,14,"bone",8],["skull",40,150,7],["skull",54,150,7],["skull",47,140,7],["skull",210,146,7],["skull",224,146,7]]},"sanctum":{"name":"The Black Sanctum","desc":["A vaulted chamber hewn from living rock. Black candles burn in iron stands, giving off a greasy, choking smoke. An inverted cross hangs above a black altar, upon which lies a book bound in what you sincerely hope is not human skin.",{"if":"!flag:circle_broken","text":"A great pentagram is cut into the floor, glowing a sullen red, and within it something shifts - a darkness with eyes."},{"if":["flag:circle_broken","!flag:banished"],"text":"The pentagram is broken, and the THING within it is free and coming for you!"},{"if":"flag:banished","text":"The pentagram is scorched and dead. The darkness that dwelt here is gone."},"The catacombs are south."],"exits":{"south":{"to":"catacombs","if":{"any":["!flag:circle_broken","flag:banished"]},"msg":"The demon flows between you and the passage. There is no way out but through it!"}},"art":[["bg","black"],["dither",0,0,256,140,"blood","black"],["poly",[0,0,256,0,256,20,128,4,0,20],"black"],["cross",128,96,44,"darkstone",true],["altar",92,132,72,26,"black","darkred"],["if","here:grimoire",[["rect",116,102,24,4,"skin","darkbrown"]]],["candle",40,120,18,"black"],["candle",216,120,18,"black"],["candle",70,110,14,"black"],["candle",186,110,14,"black"],["rect",0,140,256,52,"darkstone"],["if","!flag:circle_broken",[["glow",128,166,70,"red",0.5],["pentagram",128,166,60,"ember",0.3]],[["pentagram",128,166,60,"darkgray",0.3],["line",[100,162,140,172],"darkstone",4]]],["if","!flag:banished",[["ellipse",128,150,18,30,"black"],["circle",122,140,2,"ember"],["circle",134,140,2,"ember"]]]]}},"items":{"gate":{"name":"iron gate","at":"road","scenery":true,"open":false,"desc":[{"if":"open:gate","text":"The iron gate stands open.","else":"A tall iron gate, scabbed with rust. It isn't locked - just shut."}],"openMsg":"The gate shrieks on its hinges as you force it open. The crow takes flight, cawing."},"crow":{"name":"crow","at":"road","scenery":true,"desc":"The crow regards you with one black eye, as if it has seen people like you go in before.","on":{"attack,take,catch":"The crow hops just out of reach and croaks derisively."}},"notice":{"name":"notice","nouns":["sign","paper"],"at":"gatehouse","scenery":true,"desc":"A yellowed notice, nailed to the wall.","text":"BY ORDER OF HIS GRACE THE BISHOP: THIS HOUSE IS CLOSED. LET NO ONE ENTER. - Anno Domini 1749"},"frescoes":{"name":"frescoes","nouns":["fresco","saints","eyes","walls"],"at":"gatehouse","scenery":true,"desc":"The saints' eyes have been gouged out with something sharp. Recently, by the look of the fresh plaster dust."},"well":{"name":"stone well","nouns":["crank"],"adj":["rusted","rusty"],"at":"courtyard","scenery":true,"desc":"An old stone well with a rusted crank. A rope runs down into the darkness. Far below, water glints.","on":{"turn,pull,use":{"if":"!flag:bucket_up","do":["Groaning and squealing, the crank turns. Hand over hand a dripping wooden bucket rises out of the depths and swings at the lip of the well.",{"set":"bucket_up","show":"bucket"}],"else":["The crank is jammed now that the bucket is up."]},"climb,enter":"The shaft is narrow, slick, and far too deep. You'd never climb back out.","search":{"if":"!flag:bucket_up","do":"You can't see much - just a rope disappearing into black water.","else":[{"if":"at:iron_key:bucket","then":"There's something in the bucket.","else":"You find nothing more."}]}}},"well_rope":{"name":"rope","nouns":["rope"],"adj":["well"],"at":"courtyard","scenery":true,"desc":"A frayed rope, wound around the well's crank.","on":{"pull,turn,take":{"if":"!flag:bucket_up","do":["You haul on the rope. Groaning, a dripping wooden bucket rises out of the depths and swings at the lip of the well.",{"set":"bucket_up","show":"bucket"}],"else":["The rope is already wound up tight."]}}},"bucket":{"name":"wooden bucket","at":"courtyard","hidden":true,"scenery":true,"container":true,"fixedMsg":"The bucket is chained to the well rope.","desc":"A slimy wooden bucket, chained to the well rope."},"iron_key":{"name":"iron key","adj":["heavy","large","abbot's"],"at":"bucket","points":5,"desc":"A heavy iron key. Its bow is worked into the shape of a mitre - the abbot's mark.","art":[["circle",-5,-4,3,null,"darkgray",2],["line",[-2,-4,9,-4],"darkgray",2],["line",[7,-4,7,-1],"darkgray",2]]},"shovel":{"name":"shovel","nouns":["spade"],"adj":["rusty"],"at":"shed","desc":"A rusty shovel with a split handle. Still serviceable.","art":[["line",[-10,0,10,-22],"wood",2],["poly",[-14,2,-8,-5,-3,0,-9,6],"gray"]]},"pots":{"name":"pots","nouns":["rakes","twine","pot","rake","tools"],"at":"shed","scenery":true,"desc":"Junk. Nothing you need."},"headstone":{"name":"headstone","nouns":["headstones","stone","stones","gravestone"],"at":"cemetery","scenery":true,"desc":"Most of the stones are worn smooth. The newest bears only a carved cross and a line of text.","text":"HERE LIES BROTHER ANSELM, WHO KEPT THE LIGHT. HE SHALL GUARD IT STILL."},"grave":{"name":"grave","nouns":["earth","dirt","mound"],"adj":["new","newer","nameless"],"at":"cemetery","scenery":true,"desc":[{"if":"flag:dug","text":"A shallow open grave. Brother Anselm's bones lie at peace at the bottom.","else":"The earth on this grave is softer than the others."}]},"crucifix":{"name":"silver crucifix","nouns":["cross"],"adj":["silver","holy"],"at":"cemetery","hidden":true,"points":10,"here":"A silver crucifix gleams in the open grave.","desc":"A heavy silver crucifix. It is warm to the touch, and seems to shine with a light of its own.","art":[["cross",0,0,16,"silver"],["glow",0,-10,10,"white",0.4]]},"font":{"name":"stone font","nouns":["water","basin","font"],"adj":["holy","stone"],"at":"nave","scenery":true,"desc":"A stone font of holy water. Remarkably, the water is still clear and pure, untouched by whatever has fouled this place.","on":{"drink":"You sip the holy water. You feel a little braver."}},"sigils":{"name":"sigils","nouns":["symbols","sigil","symbol","writing"],"at":["nave","sanctuary"],"scenery":true,"desc":"Sigils of summoning and binding, daubed in what you very much hope is paint. One shape repeats over and over: a five-pointed star within a circle."},"pews":{"name":"pews","nouns":["pew","bench","benches"],"at":"nave","scenery":true,"desc":"Overturned and smashed, as if something very strong passed through in a rage."},"altar":{"name":"high altar","at":"sanctuary","scenery":true,"desc":"The altar has been stripped of its cloths and its cross. Gouges in the stone spell out words in a language you don't know.","on":{"push,pull":"The altar is a solid block of stone. It doesn't budge."}},"statue":{"name":"statue","nouns":["virgin","mary","niche","madonna"],"adj":["stone"],"at":"sanctuary","scenery":true,"desc":[{"if":"flag:statue_moved","text":"The statue has been slid aside on hidden runners.","else":"A stone statue of the Virgin. Her eyes are cast down - at the floor beneath her feet. The stone around her base is scratched in a curving arc."}],"on":{"push,pull,turn":{"if":"!flag:statue_moved","do":["You put your shoulder to the statue and heave. With a grinding of stone it slides aside on hidden runners, revealing a narrow stair leading down into darkness. A warm, foul draught rises from below.",{"set":"statue_moved"},{"exit":"sanctuary","dir":"down","to":"crypt"}],"else":["It won't move any further."]},"pray":"You kneel before the statue and pray. For a moment, the oppressive air seems to lift."}},"cabinet":{"name":"cabinet","nouns":["cupboard","wardrobe"],"adj":["tall"],"at":"vestry","scenery":true,"container":true,"open":false,"desc":[{"if":"open:cabinet","text":"A tall oak cabinet, standing open.","else":"A tall oak cabinet with brass handles. It is closed."}]},"candle":{"name":"beeswax candle","nouns":["candle","light"],"adj":["beeswax","wax"],"at":"cabinet","lightable":true,"lit":false,"lightWith":"tinderbox","needMsg":"You have nothing to light it with.","desc":[{"if":"lit:candle","text":"A thick beeswax candle, burning with a steady flame.","else":"A thick beeswax church candle. It is not lit."}],"lightMsg":"You strike the tinderbox. Sparks catch the wick, and the candle burns with a clear, steady flame.","outMsg":"You pinch out the candle.","art":[["if","lit:candle",[["candle",0,0,10,"buff"]],[["candle",0,0,10,"buff",false]]]]},"vestments":{"name":"vestments","nouns":["vestment","pegs"],"at":"vestry","scenery":true,"desc":"Rotting vestments, eaten through by moths. One plain monk's robe looks wearable."},"robe":{"name":"monk's robe","nouns":["robe","habit","cowl"],"adj":["monk's","brown","plain"],"at":"vestry","wearable":true,"here":"A plain monk's robe hangs from a peg.","desc":"A coarse brown monk's robe with a deep cowl.","art":[["poly",[-5,0,5,0,3,-18,-3,-18],"brown","black"]]},"bell":{"name":"bronze bell","nouns":["bell","rope"],"adj":["bronze","great","bell"],"at":"belltower","scenery":true,"desc":"A great bronze bell, green with age. Its rope trails to the floor.","on":{"ring,pull,push,hit,attack":{"if":"!flag:bats_gone","do":["You haul on the rope. BOOONG! ... BOOONG! ... The bell's voice rolls out over the monastery like thunder. From somewhere far beneath your feet comes a thin, rising shriek - a thousand bats, fleeing the holy sound out into the night.",{"set":"bats_gone","score":5}],"else":["The bell tolls again, long and mournful. Nothing else stirs."]}}},"table":{"name":"long table","nouns":["table"],"adj":["oak","long"],"at":"refectory","scenery":true,"container":true,"surface":true,"desc":"A long oak table set with pewter plates, stone-hard bread and dried-out wine jugs."},"bread":{"name":"bread","nouns":["loaf","food","wine","jugs","plates"],"at":"refectory","scenery":true,"desc":"Petrified. You could break a tooth on it.","on":{"eat,drink":"It has long since turned to stone and dust."}},"chalice":{"name":"silver chalice","nouns":["cup","goblet"],"adj":["silver"],"at":"table","points":5,"desc":"A beautiful silver chalice, chased with grapevines. The only thing of value that wasn't stolen or smashed.","art":[["poly",[-4,-14,4,-14,2,-8,-2,-8],"silver"],["rect",-1,-8,2,6,"silver"],["rect",-4,-2,8,2,"silver"]]},"hearth":{"name":"hearth","nouns":["fireplace","fire","ashes","ash"],"at":"kitchen","scenery":true,"desc":"A cold hearth full of old ash.","on":{"search":"You sift through the ashes. Nothing but charcoal and the tiny bones of what might have been a cat."}},"tinderbox":{"name":"tinderbox","nouns":["box","flint","tinder"],"at":"kitchen","desc":"A small tin tinderbox containing flint, steel and dry tinder.","art":[["rect",-6,-5,12,5,"gray","black"],["line",[-6,-3,6,-3],"black"]]},"flask":{"name":"glass flask","nouns":["flask","bottle","vial"],"adj":["glass","empty"],"at":"kitchen","desc":"A small stoppered glass flask. It's empty.","art":[["poly",[-4,0,4,0,4,-6,1,-9,1,-13,-1,-13,-1,-9,-4,-6],"lightgray","black"]],"on":{"fill,put,dip":{"if":"near:font","do":["You fill the flask from the font. The holy water seems to glow faintly in the glass.",{"destroy":"flask","give":"holy_water"}],"else":["There's nothing here to fill it with."]}}},"holy_water":{"name":"flask of holy water","nouns":["flask","water","bottle","vial"],"adj":["holy","glass"],"at":null,"desc":"The flask is full of holy water. It glows faintly.","art":[["poly",[-4,0,4,0,4,-6,1,-9,1,-13,-1,-13,-1,-9,-4,-6],"cyan","black"]],"on":{"drink":"That would be a waste of something precious.","pour,throw,sprinkle":{"if":["in:sanctum","!flag:circle_broken"],"do":["You hurl the holy water across the glowing pentagram. Where it lands the red lines hiss and boil, and the light gutters out. The circle is broken!\n\nThe thing inside SCREAMS - and then the scream becomes laughter. It is no longer bound. It uncoils from the dead circle and turns its burning eyes toward you...",{"set":"circle_broken","destroy":"holy_water","score":15},{"give":"flask"}],"else":["You'd better save the holy water for when it's really needed."]}}},"pallet":{"name":"straw pallet","nouns":["pallet","bed","straw","mattress"],"adj":["straw"],"at":"cells","scenery":true,"desc":"A slashed straw pallet. Someone was searching for something - or hiding something.","on":{"search":{"if":"hidden:note","do":["Deep in the straw your fingers find a folded scrap of paper.",{"show":"note","move":"note","to":"here"}],"else":["There's nothing else in the straw."]}}},"note":{"name":"scrap of paper","nouns":["note","paper","scrap"],"adj":["folded"],"at":"cells","hidden":true,"desc":"A scrap of paper covered in hurried, shaking handwriting.","text":"\"They meet below, every night now. The Abbot has gone over to Them. God forgive me, I took his key and gave it to the well - only water may find it now. If any read this: the Thing is bound by the circle. Break the circle and it is free - so have the Words ready. - Br. Anselm\"","art":[["rect",-5,-2,10,3,"buff","black"]]},"abbot_door":{"name":"oak door","nouns":["door","seal"],"adj":["oak","heavy","abbot's"],"at":["cells","abbot"],"scenery":true,"open":false,"locked":true,"key":"iron_key","desc":"A heavy oak door, sealed with red wax stamped with a mitre.","unlockMsg":"The iron key turns stiffly in the lock. The wax seal cracks and falls away."},"desk":{"name":"writing desk","nouns":["desk"],"adj":["writing","abbot's"],"at":"abbot","scenery":true,"container":true,"surface":true,"desc":"A handsome walnut writing desk."},"tapestry":{"name":"tapestry","nouns":["judgment","damned"],"at":"abbot","scenery":true,"desc":"The Last Judgment. Christ sits enthroned above, but the artist has lavished all his care on the demons below - and on one in particular, a shape of darkness with burning eyes, crouched in a circle of fire.","on":{"search,pull":"You look behind the tapestry. Only cold stone."}},"diary":{"name":"leather diary","nouns":["diary","journal","book"],"adj":["leather","abbot's"],"at":"desk","desc":"The abbot's diary, bound in black leather.","text":"Most of the entries are in a cramped Latin cipher. The last pages are plain enough:\n\n\"...the Master is pleased. The way down lies beneath Our Lady's feet - she yields to a firm shoulder. The fool Anselm prattles of his Liber Lucis and its Words of Banishing; I have locked it in its case and hidden the little key among the scribes' clutter. Let the bells ring all they like; my winged children guard the passage to the Sanctum. Without the protection of the Holy Rood no man may even approach it...\"","on":{"read":{"do":[{"set":"read_diary"}],"continue":true}},"art":[["rect",-6,-4,12,4,"darkbrown","black"]]},"glass_case":{"name":"glass case","nouns":["case","pedestal","glass"],"adj":["glass"],"at":"library","scenery":true,"container":true,"open":false,"locked":true,"key":"small_key","transparent":true,"desc":"A glass case with a small brass lock, set upon a carved pedestal.","on":{"break,attack,kick":"The glass is thick, and breaking a reliquary case feels like a very bad idea here."}},"books":{"name":"books","nouns":["shelves","shelf","bookshelf","bookshelves"],"adj":["rotting","tall"],"at":"library","scenery":true,"desc":"Psalters, lives of the saints, herbals. Damp has rotted most of them into pulp.","on":{"read,search":"You leaf through a few. Nothing useful - except that several books on demonology have their pages carefully annotated in the abbot's hand."}},"liber":{"name":"Liber Lucis","nouns":["book","volume","lucis","liber"],"adj":["white","holy","leather"],"article":"the","at":"glass_case","points":10,"desc":"The Liber Lucis - the Book of Light - bound in white leather. Its pages glow faintly in the dark.","text":"One passage is marked with a ribbon:\n\n\"BEGONE, UNCLEAN SPIRIT, BY THE LIGHT THAT WAS BEFORE THE DARKNESS!\"\n\nBeneath it, a monk has written: \"Speak these words before the Beast when it stands unbound. Then give its black book to the flame, or it shall rise again.\"","art":[["rect",-6,-4,12,4,"white","gray"],["glow",0,-2,10,"white",0.3]]},"desks":{"name":"desks","nouns":["quills","ink","pots"],"adj":["slanted","writing"],"at":"scriptorium","scenery":true,"desc":"Slanted writing desks, crusted with old ink. The largest has a drawer."},"drawer":{"name":"drawer","nouns":["drawer"],"adj":["desk"],"at":"scriptorium","scenery":true,"container":true,"open":false,"desc":"A shallow drawer in the largest desk."},"small_key":{"name":"small brass key","nouns":["key"],"adj":["small","brass","little"],"at":"drawer","desc":"A small, delicate brass key.","art":[["circle",-3,-2,2,null,"gold",1.5],["line",[-1,-2,5,-2],"gold",1.5]]},"coffins":{"name":"coffins","nouns":["coffin","lids","lid","abbots"],"adj":["stone"],"at":"crypt","scenery":true,"desc":"Stone coffins. The open ones are empty. Scratches mark the inside of the lids.","on":{"search,open":"You peer into the nearest open coffin. Empty, but for some long scratches on the inside of the lid. You decide not to dwell on it."}},"skulls":{"name":"skulls","nouns":["skull","niches","bones","bone","thighbones"],"at":["catacombs","ossuary"],"scenery":true,"desc":"Hundreds of them, staring. You could swear some of them turn to follow you."},"reliquary":{"name":"golden reliquary","nouns":["reliquary","box","casket"],"adj":["golden","gold"],"at":"ossuary","points":5,"here":"In a niche sits a golden reliquary.","desc":"A small golden reliquary set with garnets. Inside, a fingerbone wrapped in silk - the relic of St. Hilarion himself.","art":[["rect",-6,-8,12,8,"gold","darkbrown"],["poly",[-6,-8,6,-8,0,-13],"gold","darkbrown"],["circle",0,-4,1.5,"red"]]},"grimoire":{"name":"black grimoire","nouns":["grimoire","book","tome"],"adj":["black","skin","unholy"],"at":"sanctum","scenery":true,"fixedMsg":"As your fingers approach it, the book's cover ripples like flesh. You snatch your hand back.","desc":"A thick book bound in pale, stitched skin. The air above it shimmers like heat over a road.","text":"You can't bring yourself to read it."},"pentagram":{"name":"pentagram","nouns":["circle","star","floor","lines"],"adj":["great","glowing"],"at":"sanctum","scenery":true,"desc":[{"if":"!flag:circle_broken","text":"Deep grooves cut into the floor, glowing a sullen red. The air above it is foul and heavy. Whatever is inside cannot cross the lines - but nothing outside can reach it either.","else":"A broken, smoking pattern of grooves."}],"on":{"enter,touch,go":"You step toward the circle and the darkness inside lunges - stopping just at the line. Not a good idea."}},"demon":{"name":"demon","nouns":["thing","darkness","beast","eyes","shape","creature"],"adj":["dark"],"at":"sanctum","scenery":true,"desc":[{"if":"!flag:circle_broken","text":"A shape of living darkness, twice your height. Two eyes like coals regard you with hungry patience. It is bound within the circle - for now.","else":"The darkness looms over you, unbound, eyes burning."}],"on":{"attack":"You might as well attack the night sky."}},"inverted_cross":{"name":"inverted cross","nouns":["cross","candles","candle","stands"],"adj":["inverted","black","iron"],"at":"sanctum","scenery":true,"desc":"A cross hung upside-down above the black altar, ringed by black candles."},"black_altar":{"name":"black altar","nouns":["altar"],"adj":["black"],"at":"sanctum","scenery":true,"desc":"A slab of polished black stone. The skin-bound grimoire lies upon it."}},"actions":[{"verb":"dig","room":"cemetery","if":["has:shovel","!flag:dug"],"do":["You set the shovel to the soft earth of the nameless grave. A foot down, the blade rings on something metal. You brush away the soil: Brother Anselm lies here, and clasped in his bony hands is a silver crucifix. You whisper an apology and gently free it.",{"set":"dug","show":"crucifix"}],"else":[{"if":"flag:dug","then":"You've dug enough here.","else":"You claw at the earth with your fingers. It's hopeless without a proper tool."}]},{"verb":"fill","noun":["font","water"],"noun2":"flask","do":[{"if":"has:flask","then":["You fill the flask from the font. The holy water seems to glow faintly in the glass.",{"destroy":"flask","give":"holy_water"}],"else":"You have nothing to put the water in."}]},{"verb":"put","noun":["water","font"],"noun2":"flask","do":[{"if":"has:flask","then":["You fill the flask from the font.",{"destroy":"flask","give":"holy_water"}],"else":"You have nothing to put the water in."}]},{"verb":"take","noun":["water","font"],"room":"nave","do":[{"if":"has:flask","then":["You fill the flask from the font. The holy water seems to glow faintly in the glass.",{"destroy":"flask","give":"holy_water"}],"else":"You'll need something to carry the water in."}]},{"verb":"read","noun":"liber","room":"sanctum","if":["flag:circle_broken","!flag:banished"],"do":["You raise the Liber Lucis, and your voice rings out against the stone:\n\n\"BEGONE, UNCLEAN SPIRIT, BY THE LIGHT THAT WAS BEFORE THE DARKNESS!\"\n\nThe pages blaze with white fire. The demon shrieks - a sound like tearing iron - and its body unravels into smoke that is sucked down into the broken pentagram. The black candles gutter out one by one. It is gone.\n\nOnly the black grimoire remains on the altar, pulsing faintly, as if with a heartbeat...",{"set":"banished","score":20}]},{"verb":"read","noun":"liber","room":"sanctum","if":"!flag:circle_broken","do":"You read the holy words aloud, but they break against the glowing circle like waves on a rock. The circle that binds the demon also shields it. The thing inside chuckles."},{"verb":"say","noun":["begone","unclean","spirit","light"],"room":"sanctum","if":["has:liber","flag:circle_broken","!flag:banished"],"do":["You speak the Words of Banishing from the Liber Lucis. The pages blaze with white fire. The demon shrieks and unravels into smoke, sucked down into the broken pentagram. The black candles gutter out. It is gone.\n\nOnly the black grimoire remains on the altar, pulsing faintly, as if with a heartbeat...",{"set":"banished","score":20}]},{"verb":"light","noun":"grimoire","room":"sanctum","if":["flag:banished","has:candle","lit:candle"],"do":["You touch the candle flame to the corner of the grimoire. For a moment nothing happens - then the skin cover curls and blackens, and the book erupts in a roaring column of white fire that reaches to the vault. Voices scream from its pages as they burn, dozens of them, then hundreds, then silence.\n\nWhen the fire dies there is only a little grey ash, and the faint, clean smell of beeswax.\n\nYou climb back up through the crypt and out into the chapel. Through the shattered rose window, the first light of dawn is breaking over St. Hilarion's. Somewhere, a bird begins to sing.",{"score":25},{"win":"The monastery is cleansed."}],"else":[{"if":"!flag:banished","then":"As the flame nears the book, the demon's will snuffs it out like a breath. Not while its master stands.","else":"You need a lit flame to burn it."}]},{"verb":"take,read,open,touch","noun":"grimoire","if":"!flag:banished","do":[{"die":"Your fingers brush the grimoire's skin cover - and it is warm, and it MOVES. The pages fly open and a voice speaks your true name from inside them. You feel your soul pulled out through your eyes like thread through a needle.\n\nThe brothers of St. Hilarion's have a new novice."}]},{"verb":"take,read,open,touch","noun":"grimoire","if":"flag:banished","do":"Even with its master gone, you won't touch that thing with your bare hands. Better to burn it."},{"verb":"pray","room":"sanctum","if":"!flag:banished","do":"You pray. The demon laughs at you, but the laughter is a little less certain than before."},{"verb":"pray","if":"has:crucifix","do":"You grip the crucifix and pray. Warmth spreads from the silver into your hand."},{"verb":"wear","noun":"robe","room":"sanctum","do":["You pull on the robe. The demon is not fooled.",{"prop":"robe","key":"worn","value":true},{"give":"robe"}]},{"verb":"xyzzy,plugh","do":"A distant bell tolls once. Wrong game, pilgrim."},{"verb":"show,wave","noun":"crucifix","room":"sanctum","do":"You hold the crucifix high. The demon recoils, hissing - but it does not leave."}],"events":[{"if":["in:sanctum","flag:circle_broken","!flag:banished"],"do":[{"var":"demon","add":1},{"if":"var:demon>=3","then":[{"die":"The darkness closes around you like a fist. The last thing you see are the two burning eyes, very close now, and very amused."}],"else":[{"if":"var:demon==1","then":"The demon drifts out of the broken circle toward you. You haven't much time!","else":"The demon is nearly upon you! Its breath is cold as the grave."}]}]},{"if":"dark","do":[{"var":"darkturns","add":1},{"if":"var:darkturns>=4","then":[{"die":"In the blackness something cold and bony closes around your ankle and pulls. You fall, and hands - so many hands - drag you down among the bones."}],"else":[{"if":"var:darkturns==2","then":"Something skitters through the bones nearby. You'd better find some light."}]}]},{"if":"!dark","do":[{"var":"darkturns","value":0}]}]},"adventures/postcard-tour.json":{"format":"gta-1","id":"postcard-tour","title":"THE POSTCARD TOUR","author":"A tiny demo of rooms drawn from image URLs (photos from Wikimedia Commons)","theme":"paper","maxScore":15,"start":"stonehenge","overlayItems":false,"intro":"A short demo: every room here uses a photograph loaded from a URL instead of vector art. If a picture can't load, the room's vector \"art\" is drawn instead.\n\nYour aunt has sent you on a postcard tour of Europe. Find the three stamps and post your card from the castle.","help":"Try LOOK, TAKE STAMP, EXAMINE STONES, and the directions N/S/E/W. PUT STAMP ON CARD, then POST CARD at the castle.","rooms":{"stonehenge":{"name":"Stonehenge","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stonehenge2007_07_30.jpg?width=640","desc":"Great grey sarsen stones stand in a ring on Salisbury Plain, as they have for some five thousand years. A road leads east - to a ferry, and the continent.","exits":{"east":"hallstatt"},"art":[["gradient",0,120,"sky","white"],["ground",120,"grass"],["rect",60,70,18,60,"stone","black"],["rect",100,66,18,64,"stone","black"],["rect",56,62,66,10,"stone","black"],["rect",150,72,18,58,"stone","black"],["rect",190,76,16,54,"stone","black"],["rect",146,66,64,10,"stone","black"]]},"hallstatt":{"name":"Hallstatt","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hallstatt_300.jpg?width=640","desc":"A tiny Austrian village clings to the shore of a mirror-still lake beneath wooded mountains. A church spire rises above the rooftops. Roads lead west and north.","exits":{"west":"stonehenge","north":"castle"},"art":[["gradient",0,100,"sky","white"],["mountains",110,"darkgreen",5,70],["water",130,"water"],["house",40,130,30,24,"white","darkred"],["house",90,130,26,20,"buff","brown"],["rect",150,70,10,60,"white","black"],["poly",[148,70,162,70,155,46],"darkgreen","black"]]},"castle":{"name":"Neuschwanstein","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neuschwanstein_Castle_LOC_print.jpg?width=640","desc":"A fairy-tale castle of white stone and slender towers perches on a crag above a gorge. Beside the gate is a bright yellow postbox. The road leads south.","exits":{"south":"hallstatt"},"art":[["gradient",0,120,"sky","white"],["mountains",120,"darkgreen",9,40],["rect",100,50,60,70,"white","black"],["rect",90,30,14,90,"white","black"],["poly",[88,30,106,30,97,10],"navy"],["rect",156,40,12,80,"white","black"],["poly",[154,40,170,40,162,20],"navy"],["rect",200,150,14,24,"yellow","black"]]}},"items":{"card":{"name":"postcard","nouns":["card","postcard"],"at":"player","container":true,"surface":true,"desc":"A picture postcard addressed to your aunt. It needs three stamps."},"stamp1":{"name":"British stamp","nouns":["stamp"],"adj":["british","red"],"at":"stonehenge","here":"A red British stamp is caught in the grass at the foot of a stone.","points":5},"stamp2":{"name":"Austrian stamp","nouns":["stamp"],"adj":["austrian","blue"],"at":"hallstatt","here":"A blue Austrian stamp flutters on the jetty.","points":5},"stamp3":{"name":"German stamp","nouns":["stamp"],"adj":["german","green"],"at":"castle","here":"A green German stamp lies by the castle gate.","points":5},"stones":{"name":"stones","nouns":["stones","stone","sarsens","ring"],"at":"stonehenge","scenery":true,"desc":"Lichen-spotted sarsens, some capped with lintels. Nobody is quite sure why they were built."},"lake":{"name":"lake","nouns":["lake","water","village","spire","church"],"at":"hallstatt","scenery":true,"desc":"The lake is so still the village appears twice."},"postbox":{"name":"postbox","nouns":["postbox","mailbox","box"],"adj":["yellow"],"at":"castle","scenery":true,"desc":"A bright yellow Deutsche Post box."}},"actions":[{"verb":"post,mail,send,put","noun":"card","room":"castle","if":["at:stamp1:card","at:stamp2:card","at:stamp3:card"],"do":[{"destroy":"card"},{"win":"You drop the postcard into the yellow box. Somewhere, an aunt will be very pleased. That's the end of this little demo - now try loading any adventure JSON from a URL!"}],"else":"The card needs all three stamps on it first. (PUT STAMP ON CARD)"},{"verb":"post,mail,send","noun":"card","do":"You'll need a postbox."}]}};
